insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 9', 'Career Technology', 'career technology', 'Health and Safety', 'Personal Hygiene and Food Hygiene', 'B9.1.1.1', 'Demonstrate skills that relate to personal and food hygiene to self', 'B9.1.1.1.1', 'Practice good grooming', '1. Explain what is meant by good grooming and relate it to personal hygiene. E.g.: Good grooming means practising good hygiene techniques and general composure.; 2. Discuss good grooming practices, in groups. E.g., proper sitting, proper walking, proper talking, proper eating manners and wearing neat clothes.; 3. Discuss the importance of good grooming, in groups. E.g., Enhances one’s personality and interpersonal relationships; 4. Demonstrate good grooming practices. E.g., proper sitting, proper walking, proper talking, proper eating manners and wearing neat clothes.; 5. Write short messages on good grooming and tag them in and around the classroom, in groups.', 10),
('Basic 9', 'Career Technology', 'career technology', 'Health and Safety', 'Personal Hygiene and Food Hygiene', 'B9.1.1.1', 'Demonstrate skills that relate to personal and food hygiene to self', 'B9.1.1.1.2', 'Observe appropriate food hygiene practices', '1. Explain what is meant by food hygiene. E.g. It is the conditions and measures necessary to ensure the safety of food from production to consumption.; 2. Outline the appropriate food hygiene practices. E.g. - Wash hands before handling food. - Do not sneeze or cough near food. - Do not smoke or eat in any kitchen areas. - Put clothes/jackets/bags in a separate area away from cooking areas.; 3. Watch a video on good food hygiene practices and discuss, in groups. Note: - Always clean workshop at close of work and dispose of refuse appropriately. - Always demonstrate food hygiene practices in school/class and during practical lessons.', 20),
('Basic 9', 'Career Technology', 'career technology', 'Health and Safety', 'Personal, Workshop and Food Laboratory Safety', 'B9.1.2.1', 'Demonstrate skills that relate to personal, workshop and laboratory safety', 'B9.1.2.1.1', 'Describe procedures for reporting accidents and unsafe practices in school and in the laboratory/workshop/site', '1. Discuss the procedures for reporting accidents and unsafe practices in the laboratory/workshop/site E.g. - Check that there is no immediate risk of danger - Report to the teacher/instructor', 30),
('Basic 9', 'Career Technology', 'career technology', 'Health and Safety', 'Personal, Workshop and Food Laboratory Safety', 'B9.1.2.1', 'Demonstrate skills that relate to personal, workshop and laboratory safety', 'B9.1.2.1.2', 'Use appropriate personal protective equipment when working', '1. Identify the various personal protective equipment in groups E.g., goggles, ear muffs, gloves.; 2. Discuss the importance of wearing personal protective equipment, in groups E.g. - Decreases the likelihood of injury and illness. - Ensures a safe and happy working environment for all.; 3. Demonstrate the use of the personal protective equipment, in groups. E.g. - For eye protection—goggles/ visor face shield - For ear protection—ear muffs and plugs - Hand/finger protection—gloves, thimble - For foot protection—booths - For nose/mouth protection—nose mask; 4. Project work: Design and make personal protective equipment using compliant and resistant materials (fabrics) in groups. E.g., Nose mask, gloves, apron, cap, goggles', 40),
('Basic 9', 'Career Technology', 'career technology', 'Health and Safety', 'Personal, Workshop and Food Laboratory Safety', 'B9.1.2.1', 'Demonstrate skills that relate to personal, workshop and laboratory safety', 'B9.1.2.1.3', 'Maintain safe working environments', '1. Explain what is meant by maintaining safe working environment E.g., Procedures for ensuring that a surrounding environment is free from dangers that can cause harm to workers; 2. Discuss the importance of keeping the working environment safe, in groups. E.g., To reduce/prevent accidents; 3. Demonstrate safety practices at workplaces. E.g. - Tag faulty equipment - Report frayed flexes - Repair/replace frayed flexes - Repair/replace broken parts of tools.; 4. Project work: Design posters to create awareness on the need to maintain a safe working environment, and post them around the school. Note: School Health Education Programme (SHEP) clubs to educate other learners, cooks, food vendors, and staff of the school on food hygiene practices. The school should form a SHEP club if there is none in the school.', 50),
('Basic 9', 'Career Technology', 'career technology', 'Health and Safety', 'Environmental Health', 'B9.1.3.1', 'Demonstrate understanding and practice of environmental health in the school/home', 'B9.1.3.1.1', 'Discuss the causes and prevention of poor sanitation in the school/home/ community/workshop/site/laboratory', '1. Discuss the causes of poor sanitation in the home, school, community, workshop/site/laboratory. E.g., Littering around, poor disposal of waste, indiscriminate defecation.; 2. Discuss ways of preventing poor sanitation in school and home. E.g., Putting bins at vantage points for waste to be put in instead of putting it on the ground.; 3. Undertake a project on the need for people to keep the school and community clean. E.g., clean-up exercise in the school and community.; 4. Undertake a project in recycling of waste, in groups. Note: Invite an expert from the District Assembly or the Community to assist with the recycling project.', 60),
('Basic 9', 'Career Technology', 'career technology', 'Health and Safety', 'Environmental Health', 'B9.1.3.2', 'Demonstrate understanding of clean energy, and Improved Cookstoves (ICS) and their accompanying fuels', 'B9.1.3.2.1', 'Discuss what is meant by clean energy and improved cookstoves and fuels', '1. Explain what is meant by clean energy. E.g., It is energy produced through means that do not pollute the atmosphere.; 2. Identify improved cookstoves and fuels; 3. Watch pictures and videos on improved cookstoves and fuels and traditional cookstoves and fuels and make comparison of them. Note: Visit the website https://www.ghacco.org for more information.; 4. Discuss what happens when clean energy is used. E.g., They are more efficient, give off less emission and are safer than the traditional cook stoves or three-stone-fires.; 5. Search and present in class, the various improved cookstoves and fuels using ICT tools and other sources. E.g., Gyapa, holy cook, gas stoves, pellets, briquettes, Liquefied Petroleum Gas (LPG).', 70),
('Basic 9', 'Career Technology', 'career technology', 'Health and Safety', 'Environmental Health', 'B9.1.3.2', 'Demonstrate understanding of clean energy, and Improved Cookstoves (ICS) and their accompanying fuels', 'B9.1.3.2.2', 'Discuss the benefits of improved cookstoves and fuels', '1. Brainstorm the benefits of improved cookstoves and fuels, in groups and present in class. E.g., They save money, protect the cook and people around against illness.; 2. Demonstrate the uses of the following stoves. E.g.; improved cookstoves and fuels; traditional stoves.; 3. In groups, plan and organise a campaign to educate the school and the community on the use and benefits of improved cookstoves.', 80),
('Basic 9', 'Career Technology', 'career technology', 'Materials for Production', 'Compliant Materials', 'B9.2.1.1', 'Demonstrate skills in selecting compliant materials for making products and artefacts', 'B9.2.1.1.1', 'Discuss the factors that influence the selection of compliant materials', '1. Review the knowledge on properties of compliant materials and safe practices of working with tools/equipment. Note: Refer to compliant materials in B7 and B8; 2. Discuss the factors that influence the selection of compliant materials E.g. - Purpose/function of product - Availability of material - Skills of designer.; 3. Demonstrate the processes involved in working with compliant materials. E.g., measuring, marking, cutting, folding, joining, surface finishing.; 4. Make artefacts from compliant materials.; 5. Display artefacts and appraise in groups.', 90),
('Basic 9', 'Career Technology', 'career technology', 'Materials for Production', 'Resistant Materials', 'B9.2.2.1', 'Demonstrate skills in selecting resistant materials for making products/artefacts', 'B9.2.2.1.1', 'Discuss the factors that influence the selection of resistant materials', '1. Review the knowledge on properties of resistant materials and safe practices of working with tools/equipment. Note: Refer to B7 and B8 on resistant materials.; 2. Discuss the factors that influence the selection of resistant materials. E.g. - Purpose/function of product - Availability of material - Skills of designer; 3. Demonstrate the processes involved in working with resistant materials E.g., Measuring and marking out, cutting/shaping.', 100),
('Basic 9', 'Career Technology', 'career technology', 'Materials for Production', 'Resistant Materials', 'B9.2.2.1', 'Demonstrate skills in selecting resistant materials for making products/artefacts', 'B9.2.2.1.2', 'Discuss the reasons why resistant materials require particular techniques and tools for their safe handling and use', '1. Explain why specific tools are used to work on specific resistant materials. E.g. Saws designed for woodwork should not be used to cut metals else the cutting edge will become blunt.; 2. Relate the correct safety precautions to the appropriate process in working with resistant materials when making an artefact. E.g. - When planning wood, check that the plane is sharp and correctly set. - When using sharp edged tools, always keep both hands behind the cutting edge. - Fix the hacksaw blade such that the teeth point away from the handle/ operator.', 110),
('Basic 9', 'Career Technology', 'career technology', 'Materials for Production', 'Smart and Modern Materials', 'B9.2.3.1', 'Demonstrate understanding of using smart and modern materials for making products/artefacts', 'B9.2.3.1.1', 'Discuss reasons for using smart and modern materials for making products/artefacts', '1. Review the knowledge on smart and modern materials and their properties. Note: Refer to B7 and B8 CT Curriculum for more information on smart and modern materials.; 2. Compare uses of smart and modern, and compliant/ resistant materials for production, and present in a table. E.g. Smart/Modern Materials Compliant/ Resistant Materials; 1. Can cause material to change shape; 1. Material shape is fixed; 2. Can cause material to change colour; 2. Material colour is permanent and revert it', 120),
('Basic 9', 'Career Technology', 'career technology', 'Materials for Production', 'Smart and Modern Materials', 'B9.2.3.1', 'Demonstrate understanding of using smart and modern materials for making products/artefacts', 'B9.2.3.1.2', 'Demonstrate techniques for making prototypes/ projects to solve problems in the environment using smart and modern materials', '1. Identify problems in the community and use smart/modern materials to make a product to solve the problem.; 2. Search for inventions and techniques on smart/modern materials products.; 3. Demonstrate the processes involved in making the prototypes/projects using smart/modern materials.; 4. Make artefact/products using smart/modern materials.; 5. Display artefacts/products for appraisal.', 130),
('Basic 9', 'Career Technology', 'career technology', 'Materials for Production', 'Food Commodities (animal and Plant Sources)', 'B9.2.4.1', 'Demonstrate skills in selecting food commodities in meal preparation', 'B9.2.4.1.1', 'Discuss how to select food commodities used for meal preparation', '1. Revise the classification of food commodities. Note: Refer to CT B7 for more information on food commodities.; 2. Describe the qualities to look out for when buying food commodities, and present in a table. E.g. Animal products Plant products Processed foods i. Meat should have a i. Fruits and i. Cans should not deep red colour vegetables should be bulging, with white or be crisp, fine and dented, or creamy fat free from rusty. bruises, ii. Fish should have ii. Root crops ii. Dried foods firm flesh and should be free should not shiny skin with from bruises be mouldy or a lot of tightly and firm to coloured. clinging scales touch; Plant products; i. Fruits and vegetables should be crisp, fine and free from bruises,; ii. Root crops should be free from bruises and firm to touch', 140),
('Basic 9', 'Career Technology', 'career technology', 'Materials for Production', 'Food Commodities (animal and Plant Sources)', 'B9.2.4.1', 'Demonstrate skills in selecting food commodities in meal preparation', 'B9.2.4.1.2', 'Discuss the basic food requirements for different members of the family', '1. Identify the different members of the family and their basic food requirements. E.g. Different members of the Basic food requirements family Toddler Body Building Protective Adolescent Body Building Protective Iron Pregnant/lactating mothers Protective Body building Iron Aged Vitamins Invalids Vitamins; 2. Review lesson on factors to consider when planning meals in', 150),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Measuring and Marking Out', 'B9.3.1.1', 'Demonstrate understanding of measuring and marking out tools and equipment', 'B9.3.1.1.1', 'Discuss tools and equipment used for measuring and marking out', '1. Identify tools and equipment used for measuring and marking out in the following trade areas: - Building site - Wood workshop - Metal/plastic workshop -; 2. Classify measuring and marking out tools and equipment under the following areas: - Building -Wood work -Metal work/plastic', 160),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Measuring and Marking Out', 'B9.3.1.1', 'Demonstrate understanding of measuring and marking out tools and equipment', 'B9.3.1.1.2', 'Demonstrate how to use the tools and equipment for measuring and marking out', '1. Demonstrate how to use measuring and marking out tools and equipment for making artefacts/products in the following areas: - Food laboratory (Kitchen) - Sewing - Building - Wood work - Metal work/plastic; 2. Select and use appropriate measuring and marking out tools to make the following products: - Wooden chair - Sheet metal funnel - Setting out a wall - Dresses—use knowledge in body measurement to make dresses/blouses - Meals—use knowledge in portion control to prepare meals for two persons; 3. Prepare a chart showing the activities and the appropriate tools used.; 4. Display charts in class for appraisal. 5.Demonstrate how to care for and maintain measuring and marking out tools used for making artefacts/products E.g. - Wash and clean tools after use - Oil metal parts of tools', 170),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Cutting/shaping', 'B9.3.2.1', 'Demonstrate the understanding of cutting/shaping tools and equipment used for making artefacts/ products', 'B9.3.2.1.1', 'Discuss tools and equipment used for cutting and shaping', '1. Identify tools and equipment for cutting and shaping in the following trade areas: - Building site - Wood workshop - Metal/Plastic workshop; 2. Select appropriate cutting and shaping tools for making the following products: - Wooden tables - Bottle opener - Bricks/blocks - Dresses (shirts/blouses) - Meals; 3. Write the procedure/steps involved in making the products.; 4. Prepare a chart showing the activities and the appropriate tools used.; 5. Display charts for appraisal.', 180),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Cutting/shaping', 'B9.3.2.1', 'Demonstrate the understanding of cutting/shaping tools and equipment used for making artefacts/ products', 'B9.3.2.1.2', 'Demonstrate how to use shaping and cutting tools and equipment for producing artefacts/products', '1. Demonstrate how to use cutting and shaping tools and equipment for making products, in groups. E.g. -Wooden cabinets - Sheet metal dust bins - Bricks/blocks - Dresses—practise more designing and cutting out on paper - Meals—practise biscuit cutting into different shapes and practise designing of fruits into different shapes e.g., water melon, pawpaw, cucumber, carrot; 2. Write the procedure/steps involved in making the products, and discuss in class.; 3. Exhibit products for appraisal.; 4. Demonstrate how to care for and maintain cutting and shaping tools and equipment used in the following trade work places: E.g. - Food laboratory (kitchen)—wash, clean and sterilise tools - Sewing workshop/laboratory—dust, wipe, oil tools - Building site—wash and dry the wooden tools - Wood workshop—clean and oil wood chisels and saws regularly- - Metal/plastic workshop—clean and oil metal parts of tools', 190),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Joining and Assembling', 'B9.3.3.1', 'Demonstrate understanding of materials. tools and equipment used for joining and assembling artefacts/products', 'B9.3.3.1.1', 'Discuss joining and assembling materials, tools and equipment used for making artefacts/products', '1. Identify tools and equipment used for joining and assembling products in the making the following trade areas: - Building site - Wood workshop - Metal/plastic workshop - Food laboratory - Sewing workshop; 2. Classify the joining and assembling tools and equipment under: - Food laboratory (kitchen)—modern methods of joining/combining food using egg white, tapioca - Sewing laboratory/workshop—use sewing machine and glue - Building site - Wood workshop - Metal/plastic workshop', 200),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Joining and Assembling', 'B9.3.3.1', 'Demonstrate understanding of materials. tools and equipment used for joining and assembling artefacts/products', 'B9.3.3.1.2', 'Demonstrate appropriate skills in the use of joining and assembling tools and equipment for making artefacts/products', '1. Demonstrate how to use materials, tools and equipment for making products/artefacts in joining and assembling products/artefacts E.g. - A wooden bookshelf - Metal scoop - Bonding a wall - Garment—sew garments from cut-out styles in cutting/shaping lesson. Use glue to join parts of the garment. Note: There are modern methods of joining parts of articles such as fusing and adhesives - Meals—use modern joining methods such as use of oats, silicon, and egg white to prepare food. E.g., Cabbage, fufu; 2. Demonstrate how to care for and maintain joining and assembling tools and equipment used for making artefacts/products, in groups. E.g. - Wash and clean tools after use. - Dry tools thoroughly before storage', 210),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Kitchen Essentials', 'B9.3.4.1', 'Demonstrate skills of selecting and purchasing kitchen essentials and understanding and skills in the choice of basic kitchen essentials', 'B9.3.4.1.1', 'Select and purchase suitable kitchen essentials to meet specific needs', '1. Discuss factors to consider in the selection and purchasing of kitchen essentials E.g. - Money available - Space for storage - Intended purpose/use - Availability of spare parts', 220),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Kitchen Essentials', 'B9.3.4.1', 'Demonstrate skills of selecting and purchasing kitchen essentials and understanding and skills in the choice of basic kitchen essentials', 'B9.3.4.1.2', 'Demonstrate understanding of using mechanical or labour- saving kitchen essentials', '1. Explain what is meant by mechanical or labour-saving kitchen essentials and give examples E.g., These are kitchen essentials that mostly use electricity to operate and are purposely for labour saving such as refrigerator, blender and food slicer.; 2. Discuss the advantages and disadvantages of using mechanical or labour-saving kitchen essentials. E.g., - Advantages— They help to save energy by speeding up the physical task involved in carrying out cooking process. - Disadvantages—They are expensive.; 3. In groups, undertake a research and present on the types of mechanical or labour- saving kitchen essentials used in the school, home and community for appraisal. Note: Internet can also be used for the research.', 230),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Kitchen Essentials', 'B9.3.5.1', 'Demonstrate understanding of application of finishes', 'B9.3.5.1.1', 'Demonstrate the techniques of applying finishes to resistant materials', '1. Identify finishes and tools for finishing resistant materials E.g. - Finishes—lacquer, paints, thinner, turpentine - Tools—brushes, spray can, roller; 2. Identify materials used for preparing surfaces of wood, metal and wall to be finished. E.g., sanding sealers, sand paper, emery cloth, filler; 3. Prepare the surface to be finished by using glass paper for wood, emery cloth for metal, and filler for walls.; 4. Demonstrate the procedure for applying finishes to resistant materials, in groups. E.g. - Mix lacquer with thinner - Apply first coat and allow to dry - Apply second coat and allow to dry; 5. Demonstrate how to wash the finishing tools after use. E.g. - Use thinner to wash brush used for applying lacquer - Use water to wash brush used for applying emulsion paint', 240),
('Basic 9', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Kitchen Essentials', 'B9.3.5.1', 'Demonstrate understanding of application of finishes', 'B9.3.5.1.2', 'Demonstrate basic skills and processes for finishing edges of articles in sewing', '1. Demonstrate how to finish the edge of articles using the following. E.g. - Lacing - Facing - Scalloping; 2. Display specimens for appraisal.', 250),
('Basic 9', 'Career Technology', 'career technology', 'Technology', 'Simple Structures and Mechanisms, Electric and Electronic Systems', 'B9.4.1.1', 'Demonstrate knowledge of mechanisms in projects construction', 'B9.4.1.1.1', 'Describe mechanisms used for making products/ artefacts', '1. Explain what is meant by mechanisms. E.g. It is a system of parts working together in a machine; a piece of machinery.; 2. Explore different types of mechanisms using ICT tools and other sources. E.g. - Pulley system - Chain and sprocket system - Gear system - Screw mechanism - The crank mechanism - Cams - Levers and linkages; 3. Identify artefacts in the environment that operate on mechanisms. E.g., bicycles, vehicles, motor bikes.; 4. Research from different sources on how mechanisms operate, in groups.; 5. Write findings and present in class for discussion.', 260),
('Basic 9', 'Career Technology', 'career technology', 'Technology', 'Simple Structures and Mechanisms, Electric and Electronic Systems', 'B9.4.1.1', 'Demonstrate knowledge of mechanisms in projects construction', 'B9.4.1.1.2', 'Describe the features and principles of operations of mechanisms', '1. Use charts, models or real objects to describe the features of the various types of mechanisms.; 2. Use simple diagrams to illustrate the operations of the various types of mechanisms. E.g. Rack and pinion, cams, levers and linkages.; 3. Discuss the advantages and disadvantages of the various types of mechanisms. E.g., Pulley system: - Advantages: No lubrication needed, quiet in operation - Disadvantage: A slip can occur; 4. Watch videos on the various types of mechanisms in operation and discuss in class. E.g. The operations of the crank, cam, rack and pinion, chain and sprockets', 270),
('Basic 9', 'Career Technology', 'career technology', 'Technology', 'Simple Structures and Mechanisms, Electric and Electronic Systems', 'B9.4.1.1', 'Demonstrate knowledge of mechanisms in projects construction', 'B9.4.1.1.3', 'Design and make simple school technology projects using two or more of the mechanisms', '1. Identify simple school projects. E.g., wall clocks, crazy snake, toy cars, bicycles, aeroplane/air craft, train, wind turbine/mill; 2. Identify compliant and resistant materials, tools and equipment for making mock- ups/prototypes. Note: Select the appropriate mechanisms based on the function of the project.; 3. Discuss the reasons for the choice of mechanisms for a particular job. E.g. - Usage (easy to use) - Availability of mechanism - Cost of mechanism - Skills of designer; 4. Plan, design and prepare a folio of products/artefacts.; 5. Make the product/artefact following the appropriate procedure. E.g., Measuring, marking out, cutting, joining and assembling; 6. Test the product for function and modifications.; 7. Write down observations and discuss in, class in groups.', 280),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Communicating Designs', 'B9.5.1.1', 'Demonstrate understanding of developing surfaces of objects for production/ manufacturing', 'B9.5.1.1.1', 'Describe prisms and pyramids and discuss the importance of developing them', '1. Identify types of prism and pyramid. E.g., - Prisms; cylinder, square prism, triangular prism, rectangular prism - Pyramids: cone, square pyramid, triangular pyramid, rectangular pyramid; 2. Sketch types of prism and pyramid. E.g., cone, square pyramid, triangular pyramid; 3. Differentiate between prisms and pyramids. E.g. Prisms have their front view in the form of rectangles, whereas, pyramids have their front view in the form of triangles; 4. Discuss the importance of developing surfaces of objects before manufacturing them. E.g. - Enables easier duplication of templates - Minimises waste of materials - Saves time spent on production', 290),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Communicating Designs', 'B9.5.1.1', 'Demonstrate understanding of developing surfaces of objects for production/ manufacturing', 'B9.5.1.1.2', 'Develop surfaces of pyramids using instruments', '1. Illustrate the techniques of developing prisms and pyramids using instruments E.g., Draw the front view and plan, and then project them to draw the surface development of the prism and pyramids.; 2. Develop surfaces of simple objects (cylinder, cone, square prism, square pyramid) to required dimensions.; 3. Cut out the shapes of developed surfaces leaving flaps for joining.; 4. Fold and join the cut-outs as expected to obtain the objects E.g., milk tin, milo tin, match box, sugar box, pizza box, funnel, Christmas hat.; 5. Plan and mount an exhibition of the objects for appraisal.', 300),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Communicating Designs', 'B9.5.1.2', 'Demonstrate understanding of orthographic projections', 'B9.5.1.2.1', 'Describe the principles of orthographic projections', '1. Explain what is meant by orthographic projection. E.g. Drawing the three views of objects in two dimensions.; 2. Discuss the principles of orthographic projections for both first and third angle orthographic projections. E.g. - For first angle (British method), the plan is projected below the front view - For third angle (American method), the plan is projected above the front view. Note: Use mock-ups to facilitate understanding 3.Sketch the symbols for first and third angle orthographic projections.; 4. Discuss the importance of drawing orthographic projections of objects. E.g., To get detailed dimensions of parts for production of artefacts/ products.', 310),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Communicating Designs', 'B9.5.1.2', 'Demonstrate understanding of orthographic projections', 'B9.5.1.2.2', '2: Draw objects in first and third angle orthographic projection', '1. Sketch objects in pictorial indicating the appropriate dimensions, and directions of the three views (front view, plan and end view).; 2. Draw the three views to the given dimensions, at their respective positions using the appropriate projection lines. Note: Draw the front view first.; 3. Indicate the dimensions on the views and label the views appropriately.; 4. Use the idea to prepare detailed drawings of artefacts to be made.; 5. Project work: Go round the community, observe artefacts and draw four (4) artefacts in both first and third angle orthographic projections.; 6. Prepare a sketch album and present in class for appraisal.', 320),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Designing', 'B9.5.2.1', 'Demonstrate knowledge of Designing', 'B9.5.2.1.1', 'Identify user requirements', '1. Explore several situations within the community.; 2. Discuss issues identified in the situations.; 3. State main issues identified for discussion.; 4. Identify needs, wants and lacks within the environment which if not addressed can lead to problems.; 5. Discuss the challenges observed in the situations, in groups.; 6. Analyse the problems and state the extent to which they affect people’s lives in the community.; 7. Write a report on the problem situation and write a suitable design brief to indicate solution to the problem.', 330),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Designing', 'B9.5.2.1', 'Demonstrate knowledge of Designing', 'B9.5.2.1.2', 'Clarify user requirements', '1. Analyse the problem graphically by developing problem analysis chart.; 2. Develop questions to address the analysis chart.; 3. Identify sources of getting information and conduct research for the design.; 4. Prepare a questionnaire and interview guide to conduct research for the design.; 5. Develop observation schedules, visit relevant places, and take appropriate photos linked to the problem and solution.; 6. Analyse the research and write a report.; 7. Study the research report and develop design specifications based on the analysis of the problem.; 8. Cross-check the specifications to ensure that all the design requirements are met.', 340),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Designing', 'B9.5.2.1', 'Demonstrate knowledge of Designing', 'B9.5.2.1.3', 'Generate Ideas', '1. Study the specifications as a guide to generate at least three possible ideas using freehand.; 2. Write short notes to describe each of the ideas.; 3. Compare the ideas with the specifications to ensure that all requirements are met.', 350),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Designing', 'B9.5.2.1', 'Demonstrate knowledge of Designing', 'B9.5.2.1.4', 'Develop the selected solution', '1. Identify the best design that meets the specifications and select it for further consideration.; 2. Indicate the reasons for selecting a design for development.; 3. Examine the selected design to identify parts that need to be modified.; 4. Redesign the selected solution to obtain the final design.', 360),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Planning for Making Artefacts/products', 'B9.5.3.1', 'Demonstrate understanding of planning for making artefacts/ products/ meals', 'B9.5.3.1.1', 'identify basic dry methods of cooking and foods that can be prepared using the method BAKING AND GRILLING', '1. Identify and describe the basic dry methods of cooking. E.g., baking, grilling; 2. Identify foods that can be prepared using the dry method of cooking. E.g. Baking—bread, cake, aboloo Grilling—plantain, fish, chicken; 3. Discuss advantages and disadvantages of baking and grilling methods of cooking. E.g. - Advantage—Promotes the caramelisation of surface sugars in foods - Disadvantage—Food can easily burn or dry out; 4. Discuss the principles of baking and grilling methods of cooking. E.g. - Baking—All ingredients need to be measured carefully. - Grilling—Marinate foods in the refrigerator, not on the kitchen counter or outdoors', 370),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Planning for Making Artefacts/products', 'B9.5.3.1', 'Demonstrate understanding of planning for making artefacts/ products/ meals', 'B9.5.3.1.2', 'Demonstrate Skills in menu planning', '1. Explain what is meant by a menu. E.g., A menu is a list of dishes or kinds of food served at a meal.; 2. Discuss the importance of planning a menu. E.g., it helps customers to be made aware of what dishes are available in the restaurant and the price per dish.; 3. Discuss the factors to consider when planning a menu. E.g. - Availability of tools, equipment and skilled personnel. - Availability of foods/foods in season.; 4. Discuss some types of menu in groups. E.g., A’ la Carte, Table d’hôtel; 5. In groups, plan a menu for discussion in class.; 6. Display planned menus for appraisal', 380),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Planning for Making Artefacts/products', 'B9.5.3.1', 'Demonstrate understanding of planning for making artefacts/ products/ meals', 'B9.5.3.1.3', 'Describe ways of using the natural building materials for production', '1. Discuss how clay/laterite is used for producing bricks/blocks. E.g. - Identify types of clay/laterite brick/block - Describe the methods of manufacturing clay/laterite bricks/blocks—extruded, moulded, dry-pressed', 390),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Planning for Making Artefacts/products', 'B9.5.3.1', 'Demonstrate understanding of planning for making artefacts/ products/ meals', 'B9.5.3.1.4', 'Demonstrate how to clarify user requirements', '1. Study the working drawings and cutting list obtained from the communication design.; 2. Observe the workshop environment to identify the health and safety needs of the work.; 3. Study workshop rules and regulations for better familiarisation before the actual work.; 4. Study about the needed materials, tools and processes to be employed for better understanding.; 5. Write down a summary of your study and observations and discuss in class.; 6. Experiment with similar materials, tools and processes to gain confidence prior to the making of artefacts.', 400),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Making Artefacts from Compliant, Resistant Materials and Food Ingredients', 'B9.5.4.1', 'Demonstrate understanding of gathering materials, tools and equipment for making/preparing meals and articles', 'B9.5.4.1.1', 'Demonstrate skills in preparing food using the dry methods of cooking', '1. Prepare a dish each using baking and grilling methods of cooking. E.g. Baking—bread, cake, aboloo Grilling—plantain, fish, chicken; 2. Display food for evaluation and appreciation.', 410),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Making Artefacts from Compliant, Resistant Materials and Food Ingredients', 'B9.5.4.1', 'Demonstrate understanding of gathering materials, tools and equipment for making/preparing meals and articles', 'B9.5.4.1.2', 'Create advanced articles using crocheting and embroidery stitches', '1. Review work on tools, equipment and stitches used in sewing and crocheting. B: Refer to B7 and B8 on stitches and crocheting.; 2. Discuss some crocheted and embroidered articles and their uses. E.g. Shoes—to protect one’s foot/feet.; 3. Make advanced articles using crocheting and design or make patterns to decorate using embroidery stitches. E.g. Hand bags, jackets/cardigans, shoes (baby and adult) and purse.; 4. Plan and mount an exhibition of products for appraisal.', 420),
('Basic 9', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Making Artefacts from Compliant, Resistant Materials and Food Ingredients', 'B9.5.4.1', 'Demonstrate understanding of gathering materials, tools and equipment for making/preparing meals and articles', 'B9.5.4.1.3', 'Demonstrate how to gather materials, tools, and equipment for making artefacts', '1. Study and examine the design folio to understand the working drawings and the operations or processes involved.; 2. Check the dimensions of the working drawings and the cutting list to ensure accuracy of work.; 3. Apply the making operations in sequence to make the artefact. Note: Decide on the materials, measuring, marking out, cutting to the complete the work; 4. Apply the appropriate finish to the artefact ready.; 5. Test the manufactured artefact using the specification as a guide. E.g., Test the shape, structure, functions, strength etc.; 6. Prepare a check list to indicate the good and bad comments about the artefact.; 7. Rate the quality of the artefact as excellent, very good, good, fair or poor.; 8. State the suggested modifications for the artefact.', 430),
('Basic 9', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Career Pathways and Career Opportunities', 'B9.6.1.1', 'Demonstrate understanding about the changing nature of the workplace, the value of work to society, and the connection of work to the achievement of personal goals', 'B9.6.1.1.1', 'Describe how the changing nature of the workplace can bring about global competition and technology', '1. Find out from various sources, how changes at the work place can bring about global competition and technology E.g. - Introduction of automation at work place - Use of ICT - Use of robots and drones - Use of machines; 2. Discuss the findings, in groups and write a summary individually.', 440),
('Basic 9', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Career Pathways and Career Opportunities', 'B9.6.1.1', 'Demonstrate understanding about the changing nature of the workplace, the value of work to society, and the connection of work to the achievement of personal goals', 'B9.6.1.1.2', 'Analyse the value of work to the individual and society in general', '1. Analyse and report the value of work to the individual and society in general, in groups.; 2. Discuss the advantages and disadvantages of working for self and others. E.g., Self: - Advantage: More control over income; choose the people you work with. - Disadvantage: Difficult to raise capital; working may be much longer and irregular; sickness results in the business suffering. Others: - Advantage: Retirement benefits; regular work hours - Disadvantage: Less job security; less freedom', 450),
('Basic 9', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Career Pathways and Career Opportunities', 'B9.6.1.1', 'Demonstrate understanding about the changing nature of the workplace, the value of work to society, and the connection of work to the achievement of personal goals', 'B9.6.1.1.3', 'Develop a career plan that would assist in the transition from school to eventual entry into a career option', '1. Discuss the need for a career plan, in groups.; 2. Identify and discuss the steps in an effective career plan. E.g. - Identify your career options - Prioritise - Make comparisons. - Consider other factors - Make a Choice; 3. Write a summary of your discussion and read to class.', 460),
('Basic 9', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Establishing and Managing a Small Business Enterprise', 'B9.6.2.1', 'Demonstrate understanding of establishing and managing a small business enterprise', 'B9.6.2.1.1', 'Describe how to start and run a small business', '1. Discuss how to start and run own business, in groups. E.g. - Own business idea - Copying an existing business - Buying an existing business - Modifying an existing business; 2. Read and a write on legal forms of businesses in Ghana, and discuss in class, in groups.; 3. Discuss how to name a business, in groups. E.g. - Giving potential names to the business, - Settle on one name as the name of the business; 4. Read on licensing/registration processes, and visit licensing/registration agencies to learn more about licensing/registration procedures.; 5. Write the summary of findings from visit and discuss in class, in groups.', 470),
('Basic 9', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Establishing and Managing a Small Business Enterprise', 'B9.6.2.1', 'Demonstrate understanding of establishing and managing a small business enterprise', 'B9.6.2.1.2', 'Explain how to manage resources of small business enterprises', '1. Think-pair-share on products and services that are in demand, and write down your views.; 2. Discuss factors to consider when running and managing a small-scale business. E.g.: - Land - Labour - Capital - Market - Location; 3. Discuss the processes of managing a business, in groups. E.g. - Planning - Organising - Communicating - Delegating - Motivating - Controlling', 480),
('Basic 9', 'Creative Arts', 'creative arts', 'Design', 'Design in Nature and Manmade Environment', 'B9.1.1.1', 'Demonstrate understanding of design as a concept in relation to the elements (form, value) and principles (variety, proportion) of design and as a medium for creative expression of design in nature and the manmade environment', 'B9.1.1.1.1', 'Demonstrate understanding of design as a concept by using the elements and principles of design as a medium for creative expression of design in nature and the manmade environment', 'Exemplar; 1. Research to determine and record the meaning, importance and role of design in nature and the manmade environment for reflection and discussion.; 2. Explore and reflect on selected natural and manmade designs to appreciate and determine how design in nature has influenced manmade designs to benefit society for appreciation and discussion. Example: form, value Design inspired by B eak of kingfisher bird inspired the palm Colourful bird Shinkansen Bullet Train – Japan Source: Pinterest.com; 3. Compare and contrast selected natural and manmade designs to determine and record their similarities and differences for reflection and inspiration to create and illustrate own design ideas (e.g. rivers/roads, anthills/houses, etc.) Source: Pinterest.com Anthill inspired Eastgate Building in Harare Zimbabwe', 10),
('Basic 9', 'Creative Arts', 'creative arts', 'Design', 'Design in Nature and Manmade Environment', 'B9.1.1.1', 'Demonstrate understanding of design as a concept in relation to the elements (form, value) and principles (variety, proportion) of design and as a medium for creative expression of design in nature and the manmade environment', 'B9.1.1.1.2', 'Research to identify and record what constitutes the ‘elements of design’ in nature and as building blocks for creative expression of design ideas', 'Exemplar; 1. Research to deduce and record what constitutes the ‘elements of design’ and their application as building blocks for creative expression of design for reflection and discussion. Examples: form, value Source: Pinterest.com', 20),
('Basic 9', 'Creative Arts', 'creative arts', 'Design', 'Design in Nature and Manmade Environment', 'B9.1.1.1', 'Demonstrate understanding of design as a concept in relation to the elements (form, value) and principles (variety, proportion) of design and as a medium for creative expression of design in nature and the manmade environment', 'B9.1.1.1.3', 'Research to identify and record in writing what constitutes the principles of design and describe how they are used to organise the elements of design into building blocks for creative expression of design in nature and the manmade environment', 'Exemplar; 5. Search for and organise relevant information to describe and record the principles of design and how they apply in nature and the manmade environment for reflection. Examples: variety, proportion Natural designs Zimbabwe Manmade design; Source: Pinterest.com 4. Identify, describe and record examples of principles of design in nature and the manmade environment for appreciation and discussion.; 5. Apply knowledge gained to select examples of elements and principles of design to create own designs using available manual and digital tools, materials and techniques for appreciation, display and feedback.', 30),
('Basic 9', 'Creative Arts', 'creative arts', 'Design', 'Drawing, Shading, Colouring and Modelling for Design', 'B9.1.2.1', 'Design Demonstrate understanding and use of (3- D drawing, shading, colouring and modelling) media and techniques for creative expression of design ideas', 'B9.1.2.1.1', 'Explore available manual and digital tools, materials and techniques for 3-D drawing, shading and colouring to create designs from lines, simple shapes and forms', 'Exemplar; 1. Explore to determine and document the nature and suitability of available manual tools, materials and techniques for 3-D drawing, shading, and colouring for appreciation and reflection. E.g. of tools: T-square, set square, protractor/paper/cardboard/pencil. Tools and materials drawing Source: Googlecom', 40),
('Basic 9', 'Creative Arts', 'creative arts', 'Design', 'Drawing, Shading, Colouring and Modelling for Design', 'B9.1.2.1', 'Design Demonstrate understanding and use of (3- D drawing, shading, colouring and modelling) media and techniques for creative expression of design ideas', 'B9.1.2.1.3', 'Demonstrate ability to generate design ideas and develop models of simple shapes and forms for appreciation and display', 'Exemplar; 6. Identify simple products and generate drawings to illustrate templates for creating models of simple shapes and forms using cardboard, Styrofoam, pulp paper and/or clay for reflection, display and appreciation.; 7. Develop own drawings of templates and create models of simple shapes and forms using cardboard, Styrofoam, clay and/or pulp paper for appreciation and sharing.; 3. Display own 3-D drawings, templates and models of simple shapes and forms for appreciation, appraisal and feedback.', 50),
('Basic 9', 'Creative Arts', 'creative arts', 'Design', 'Drawing, Shading, Colouring and Modelling for Design', 'B9.1.3.1', 'Design Demonstrate understanding of creativity and innovation in terms of the design process, and its application in developing design solutions to problems in society', 'B9.1.3.1.1', 'Distinguish between creativity and innovation and their application for developing design solutions to problems in society', 'Exemplar; 1. Research and define the key differences between creativity and innovation for reflection and discussion.; 2. Apply knowledge of creativity and innovation to evaluate the design products that solve specific problems in society for appreciation. Example: Energy conservation, Energy efficiency etc; 3. Examine specific artefacts available in the local community and report on specific challenges associated with their design for reflection and discussion. Example: cutlass in farming, kitchen stool, basket for farming,', 60),
('Basic 9', 'Creative Arts', 'creative arts', 'Design', 'Drawing, Shading, Colouring and Modelling for Design', 'B9.1.3.1', 'Design Demonstrate understanding of creativity and innovation in terms of the design process, and its application in developing design solutions to problems in society', 'B9.1.3.1.2', 'Demonstrate understanding of the design process in relation to creativity and innovations in design', 'Exemplar; 1. Research and record the concept, importance and application of the design process in creative problem solving for reflection and discussion. Examples: define, brief, research, ideation, invent, prototype, testing, refine.; 2. Analyse information gathered and describe the steps in the design process in relation to creativity and innovation for appreciation and sharing.; 3 Evaluate the design of different products and suggest ways in which they could be modified to solve other problems in society.', 70),
('Basic 9', 'Creative Arts', 'creative arts', 'Design', 'Drawing, Shading, Colouring and Modelling for Design', 'B9.1.3.1', 'Design Demonstrate understanding of creativity and innovation in terms of the design process, and its application in developing design solutions to problems in society', 'B9.1.3.1.3', 'Demonstrate ability to apply the design process to create artefacts that solve specific problems in the local community', 'Exemplar; 1. Apply knowledge of creativity and innovation to evaluate specific problems in society to deduce how the design process can be used to solve those problems for reporting and feedback.; 2. Reflect on feedback and apply relevant manual and digital tools, materials and techniques to design and create model artefacts that express own concept for solving specific problems in society for appreciation and display.; 3. Display design expressions and prototypes of artefacts to disseminate own creativity and innovation for appreciation and feedback.', 80),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.1', 'Visual Arts: Demonstrate understanding and apply media and techniques in casting, assemblage and folding', 'B9.2.1.1.1', 'Explore and identify media and techniques used to create visual artworks by casting, assemblage and folding', 'Exemplars 1. Identify, describe, discuss and record information on available tools, materials and equipment from a variety of sources for casting, assemblage and folding. Examples: from videos/illustrations/pictures/realia 2. Test, classify and discuss the use of the tools, materials, equipment according to their findings on casting, assemblage and folding. 3. Apply the tools, materials and equipment safely and skilfully to create own artefacts using casting, assemblage and folding techniques and display them for appraisal using peer- and self-evaluation to review work for feedback. Examples of art specific language vocabulary: casting, assemblage and folding. 4. Apply knowledge and skills in safety, maintenance and sustainability to organise and store tools, materials and equipment, and clean up the work space.', 90),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.1', 'Visual Arts: Demonstrate understanding and apply media and techniques in casting, assemblage and folding', 'B9.2.1.1.2', 'Experiment by using techniques in casting to create visual artworks', 'Exemplars 1. Identify the techniques in casting such as filled-in, hump and hollow to create own cast artworks. 2. Design own cast artworks and apply the relevant techniques of casting to create own visual artworks for display and feedback. 3. Display cast artworks for appreciation, reflection and review using peer- and self-evaluation for feedback. Examples of art specific language vocabulary: form, casting, hump and hollow.', 100),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.1', 'Visual Arts: Demonstrate understanding and apply media and techniques in casting, assemblage and folding', 'B9.2.1.1.3', 'Apply artistic techniques in folding by using available media to make creative artworks', null, 110),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.1', 'Visual Arts: Demonstrate understanding and apply media and techniques in casting, assemblage and folding', 'B9.2.1.1.4', 'Exemplar 1 Types of objects used: found objects in the environment How objects were joined: stitching, gluing, stapling etc.,', '3. Display constructed artworks for appreciation, reflection and use peer- and self-evaluation to review work. Examples of art specific language vocabulary: form, line, texture, colour, texture, shape.', 120),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.2', 'Performing Arts - Music: Demonstrate knowledge, understanding and application of triads, chord progression and improvisation in music', 'B9.2.1.2.5', 'Sing in pitch triads on all the seven degrees of the scale horizontally (arpeggios) and vertically (harmony)', 'Exemplars 1. Sing and/or perform on melodic instruments triads built on all the seven degrees of the scale melodically. Sing through the triads as technical exercise arpeggios. Hold last notes at ends (long pause). 2. Sing and/or perform on keyboard/melodic instruments triads built on all the seven degrees of the scale harmonically. Group 1 d’ r’ m’ f’ s’ l’ t’** Group 2 s l t d’ r’ m’ f’ Group 3 m f s l t d’ r’ Group 4 d r m f s l t Degree I II III IV V VI VII Groups must be arranged from high voices to low (i.e. 1 through 4) End on the first degree to complete the cycle. **Replace [t] with [r] where highlighted because that note is not doubled in music.', 130),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.2', 'Performing Arts - Music: Demonstrate knowledge, understanding and application of triads, chord progression and improvisation in music', 'B9.2.1.2.6', 'Create/improvise a melody using (I, VI, IV, V) as the ostinato bass line', 'Exemplar 1. Rehearse an improvised melody on [d: l: f: s ] ostinato and perform the melody with voice/instrument based on [I, VI, IV and V] chord progression. E.g.,', 140),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.3', 'Dance and Drama: Demonstrate understanding and application of media and techniques in Dance and Drama', 'B9.2.1.3.7', 'Create a simple Dance Drama and/or one act based on a topical issue', 'Exemplar 1. Identify and select materials for creating a Dance Drama and/or one act play.', 150),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.3', 'Dance and Drama: Demonstrate understanding and application of media and techniques in Dance and Drama', 'B9.2.1.3.8', 'Explore and identify the various approaches to improvisation, creating harmony/balance and blocking for dance and drama', 'Exemplars 1. Identify additional parts of the performance space. Refer to the Teacher’s Resource Pack. 2. Explore the parts of the body and props essential for acting and dancing. 3. Explain masking, aside, apron, linear and circular patterns, etc., in dance and drama.', 160),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B9.2.1.3', 'Dance and Drama: Demonstrate understanding and application of media and techniques in Dance and Drama', 'B9.2.1.3.9', 'Experiment and practise by using the techniques of improvisation, creation of harmony/balance and blocking in dance and drama', null, 170),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.1', 'Visual Arts: Exhibit art works produced from competences and skills acquired from the application of the philosophies, designs and processes learnt from different times and cultures', 'B9.2.2.1.1', 'Design and produce own visual artworks that reflect a range of different times, cultures and topical issues', 'Exemplars 1. Select an artist or art works from a different time or culture. Research and document the elements of design used in the art works such as colour, media, techniques, composition and content. 2. Use the information gathered on the selected artist to plan and use some of the elements of design in the art works (such as colour, media, content, composition) and the design process to create an artwork. 3. Develop and use peer- and self-evaluation criteria to review work in progress for reflection, encouragement, guidance and improvement: Examples of art specific language vocabulary: form, line, texture, colour, shape, unity, balance, variety, harmony, technique, media.', 180),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.1', 'Visual Arts: Exhibit art works produced from competences and skills acquired from the application of the philosophies, designs and processes learnt from different times and cultures', 'B9.2.2.1.2', 'Plan and display artworks that reflect the influence of a range of different times, cultures and topical issues', 'Exemplars 1. Investigate and apply the knowledge and skills in organising exhibition in Visual Arts paying attention to peculiarity of artefacts involved, target audience, space/venue, finance, publicity, etc. 2. Collaborate to analyse and present reports on the similarities, differences and challenges in preserving and exhibiting art works.', 190),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.1', 'Visual Arts: Exhibit art works produced from competences and skills acquired from the application of the philosophies, designs and processes learnt from different times and cultures', 'B9.2.2.1.3', 'Organise an appreciation and appraisal of artworks produced using inspiration and ideas from different times, cultures and other relevant topical issues', 'Exemplars 1. Appreciate and appraise an artwork by using criteria that covers the form, content, elements and principles, purpose, cultural traditional/ contemporary impact. 2. Plan and organise a class exhibition and do self and peer review on exhibits.', 200),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.2', 'Performing Arts - Music: Exhibit competences in the application of the design process to produce and display own creative musical work that reflect a range of different times, cultures and topical issues', 'B9.2.2.2.4', 'Design and produce own musical work that reflects a range of different times and cultures that promote and sensitise the public on emerging topical issues', '2. Reflect and refine own work using the feedback from the appraisal and aesthetic appreciation report.; 3. Disseminate the findings of your research to the class by giving a presentation.', 210),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.2', 'Performing Arts - Music: Exhibit competences in the application of the design process to produce and display own creative musical work that reflect a range of different times, cultures and topical issues', 'B9.2.2.2.5', 'Plan and display own and others’ musical works within the African continent that promote and sensitise the public on emerging topical issues', null, 220),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.2', 'Performing Arts - Music: Exhibit competences in the application of the design process to produce and display own creative musical work that reflect a range of different times, cultures and topical issues', 'B9.2.2.2.6', 'Organise an appreciation and appraisal of own original musical works and those of others on the African continent that promote and sensitise the public on emerging topical issues', null, 230),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.3', 'Dance and Drama: Producing a dance drama', 'B9.2.2.3.7', 'Perform an original dance drama and/or one act play on socio-cultural issues', 'Exemplar 1. Rehearse and perform the original dance drama and/or one act play you created with your identified and selected materials to a selected audience. Example of play titles: SSNIT Pension Scheme services, Sanitation, Energy etc.', 240),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.3', 'Dance and Drama: Producing a dance drama', 'B9.2.2.3.8', 'Post-performance analysis of the original dance drama and/ or one act play', 'Exemplar 1. Reflect on the audience response and prescribe areas of improvement. Example of plays to prescribe: SSNIT Pension Scheme services, Sanitation, Energy etc.', 250),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B9.2.2.3', 'Dance and Drama: Producing a dance drama', 'B9.2.2.3.9', 'Organise an appreciation and appraisal of own and others’ dance and drama artworks that reflect a range of different times, cultures and topical issues', 'Exemplars 1. Invite an audience to watch the performance of own and others for appreciation and appraisal. Example of performance: SSNIT Pension Scheme services, Sanitation, Energy etc. 2. Note and record the strengths and weaknesses of the production and performance for discussion and modification of future performances.', 260),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B9.2.3.1', 'Visual Art Demonstrate the skill to correlate and generate ideas from creative artworks of African artists that reflect a range of different times, cultures and topical issues', 'B9.2.3.1.1', 'Identify, discuss, and analyse creative artworks of African visual artists that reflect their background, influence and way of solving continental issues', 'Exemplars 1. Scout for, gather and classify information on prominent African visual artists and record their respective artworks according to disciplines. Example: Tribe, Education, Philosophy and Competition/ Exhibition, Achievements etc. (Ablade Glover, Dorothy Amenuke, Saka Aquaye, etc 2. Reflect, discuss and appreciate prominent African visual artists, their motivation and inspiration in solving environmental and continental issues. 3. Analyse and make presentations on the contributions of artworks of prominent African visual artists in addressing continental issues.', 270),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B9.2.3.1', 'Visual Art Demonstrate the skill to correlate and generate ideas from creative artworks of African artists that reflect a range of different times, cultures and topical issues', 'B9.2.3.1.2', 'Examine and reflect on how African visual artists use their influence and personal responses to connect with other creative arts and subjects in Africa', null, 280),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B9.2.3.2', 'Performing Arts - Music: Demonstrate the skill to correlate African music that reflect the history, culture and topical issues', 'B9.2.3.2.3', 'Distinguish different ways musical works of African art composers reflect the history, culture, environment and topical issues', 'Exemplars 1. Compare Akin Euba and J. H. K. Nketia. 2. Transcribe a popular song from a composer from an African country that promotes and sensitises the public on an emerging topical issue such as climate change, war, terrorism, sanitation, social security, etc.', 290),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B9.2.3.2', 'Performing Arts - Music: Demonstrate the skill to correlate African music that reflect the history, culture and topical issues', 'B9.2.3.2.4', 'Appreciate and appraise at least three (3) African indigenous dance genres and three (3) popular musical genres from an African nation based on their style, instruments, song themes, forms, dance movements, etc', null, 300),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B9.2.3.3', 'Dance and Drama: Demonstrate the skill to correlate African dance and drama that reflect the history, culture and topical issues', 'B9.2.3.3.5', 'Reflect on a selected African creative work (dance and/or drama) and appreciate the ideas embedded', 'Exemplar 1. Discuss and document some important aspects of history, culture, and topical issues in the selected Africa creative work.', 310),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B9.2.3.3', 'Dance and Drama: Demonstrate the skill to correlate African dance and drama that reflect the history, culture and topical issues', 'B9.2.3.3.6', 'Create and perform a one act play or dance based on your selected African creative work (dance/drama)', 'Exemplar 1. Rehearse and perform a one act play and/or dance (the performance should be recorded).', 320),
('Basic 9', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B9.2.3.3', 'Dance and Drama: Demonstrate the skill to correlate African dance and drama that reflect the history, culture and topical issues', 'B9.2.3.3.7', 'Conduct a performance review', 'Exemplar 1. Arrange a live performance or view the recorded creative work for appraisal.', 330),
('Basic 9', 'English Language', 'english', 'Oral Language', 'Conversation/everyday Discourse', 'B9.1.1.1', 'Demonstrate the use of appropriate language orally in specific situations', 'B9.1.1.1.1', 'Use appropriate register in everyday communication (informal and formal) with diverse partners on grade-level topics/texts/issue', 'Identify some slang words and jargon accepted locally and internationally.; Use these in conversation on grade-level topics/texts/issues, e.g. informal (talking about music, sports, hobbies, going out with friends, social media,) the cause of poor academic performance.; Create and act scenes dialogues/skits on texts/issues/topics using both formal and informal register to distinguish characters.; Use appropriate register accurately in spontaneous conversation.', 10),
('Basic 9', 'English Language', 'english', 'Oral Language', 'Conversation/everyday Discourse', 'B9.1.1.1', 'Demonstrate the use of appropriate language orally in specific situations', 'B9.1.1.1.2', 'Ask questions that link the ideas of several speakers and respond to others’ questions in a discussion', 'Use open ended questions to enable speaker link ideas of other speakers on topics/issues. E.g. o In your opinion, what are the views of people on…? o What are the views of people on…? o How do you think we should . . .? o Why don’t you …? o Which of these do you prefer ..... ?; Listen attentively to viewpoints on topics/issues in a conversation and respond appropriately.; Engage in conversations on topics/issues with several speakers and respond to different views.', 20),
('Basic 9', 'English Language', 'english', 'Oral Language', 'Conversation/everyday Discourse', 'B9.1.1.1', 'Demonstrate the use of appropriate language orally in specific situations', 'B9.1.1.1.3', 'Use appropriate language and open-ended questions to discuss grade-level national and global issues', 'Identify grade-level national issues (the youth in agriculture, sanitation, lifestyle diseases).; Discuss grade-level national issues with several speakers, using appropriate register and open-ended questions.; Identify and explain grade - level global issues e.g., violence, gender and inclusion, kidnaping, terrorism, child trafficking.; Discuss orally, grade-level global issues/topics using appropriate language e.g. Register/Vocabulary, phrasal verbs, idioms.', 30),
('Basic 9', 'English Language', 'english', 'Oral Language', 'Conversation/everyday Discourse', 'B9.1.1.1', 'Demonstrate the use of appropriate language orally in specific situations', 'B9.1.1.1.4', 'Demonstrate appropriate turn taking and use techniques for effective argument (debating)', 'Identify interesting topic/issues appropriate for argument and debate e.g. children should be allowed to take decisions on matters concerning them.; Engage in arguments and debates on topics/issues using appropriate register. Observe and use the skills of turn taking in arguments and debates.', 40),
('Basic 9', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B9.1.2.1', 'Demonstrate the ability to listen to extended reading and identify key information', 'B9.1.2.1.1', 'Listen to audio-visual texts attentively and support ideas with vocabulary/ language/figures', 'Listen to and watch audio-visuals for about two hundred(200) words per two(2) minutes and write key information (message, theme, tone, mood, character) from them. Examples of audio -visual texts include: o Films o Television programmes o Documentaries o Recordings o Radio programmes o Music videos o Dramas; Make inferences (about purpose, intention, theme/ message) and simple connections to real life and personal experiences.', 50),
('Basic 9', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B9.1.2.1', 'Demonstrate the ability to listen to extended reading and identify key information', 'B9.1.2.1.2', 'Initiate and participate in meaningful and collaborative discussions using texts and related materials, building on others’ ideas and expressing their own clearly and persuasively', 'Listen to and identify key issues in level-appropriate texts/speeches/ dialogues e.g. argumentative texts, news, presentations.; Initiate discussions on ideas and share opinions on level-appropriate texts/speeches/dialogues.; Engage in conferences to discuss ideas noted from texts/speeches/ dialogues and express your own clearly and persuasively.', 60),
('Basic 9', 'English Language', 'english', 'Oral Language', 'English Sounds', 'B9.1.3.1', 'Articulate English speech sounds to develop confidence and skills in listening and speaking', 'B9.1.3.1.1', 'Produce /r/ and /l/ sounds in different positions in word', 'Listen to and produce /r/ and /l/ in different positions in words. Positions in words o Beginning o Middle o End; Distinguish between the sounds and reproduce them in speech.', 70),
('Basic 9', 'English Language', 'english', 'Oral Language', 'English Sounds', 'B9.1.3.1', 'Articulate English speech sounds to develop confidence and skills in listening and speaking', 'B9.1.3.1.2', 'Produce consonant clusters in context', 'Listen to texts and produce consonant clusters in context (e.g. pl, pr, cr, cl, tr, sm, sp, spl, spr, gh, etc.).; Produce consonant clusters accurately in connected speech.', 80),
('Basic 9', 'English Language', 'english', 'Oral Language', 'English Sounds', 'B9.1.3.1', 'Articulate English speech sounds to develop confidence and skills in listening and speaking', 'B9.1.3.1.3', 'Produce mono-syllabic and di-syllabic words with accurate stress in speech', 'Listen to and produce mono and di-syllabic words in context (dialogues).; Listen to and write words containing di-syllabic words, e.g. travel, visit, etc.; Produce mono and di-syllabic words accurately in speech.', 90),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.1', 'Demonstrate increasing confidence and enjoyment in independent reading', 'B9.2.1.1.1', 'Read a variety of grade level texts and demonstrate understanding', 'Read a variety of age-appropriate texts for enjoyment and knowledge.; Set specific learning purposes to be achieved at the end of the reading task.; Apply appropriate strategies to answer questions on the texts.', 100),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.1', 'Demonstrate increasing confidence and enjoyment in independent reading', 'B9.2.1.1.2', 'Reflect on how reading impacts self and others see the world (contrasting viewpoints, evaluating reasoning, determining importance or credibility)', 'Read a variety of texts.; Identify texts that give general view of oneself and others.; Identify the different points of view through different approaches and texts.; Compare the views of others in achieving success.; Peer edit information gathered.', 110),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.1', 'Demonstrate increasing confidence and enjoyment in independent reading', 'B9.2.1.1.3', 'Evaluate ways that the media helps to disseminate information via different text types', 'Gather samples of media messages/articles/stories kindle) from credible sources.; Critique these messages and suggest improvements.; Identify better ways to use the media for messaging.; Create your own articles/stories etc. and post using ICT.', 120),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.1', 'Demonstrate increasing confidence and enjoyment in independent reading', 'B9.2.1.1.4', 'Expand various ideas and perspectives in texts', 'Read a level appropriate text.; Identify the main ideas and the writer’s point of view.; Compare own ideas with other points of view.; Peer review other ideas.; Put ideas together to expand the different perspectives.', 130),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.1', 'Read given text, within a specific time, for specific information', 'Read age-appropriate texts for the main ideas.; Read within given time for specific information.; Answer simple questions on the texts.; Peer review the information gathered.', 140),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.2', 'Make predictions, identify patterns and relationships of ideas to analyse texts', 'Read a set text.; Using prediction, make a summary of the main ideas.; Follow up with other strategies to find patterns and relationships between ideas.; Put all information together and peer edit.', 150),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.3', 'Make generalisations from text and link to real life situations', 'Read a text and identify specific patterns that form generalisations.; Identify the highest points and link to real life situations.; Modify portions of texts to suit the realities of life.', 160),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.4', 'Compare the language, style, structure and purpose, as well as the ideas/information from different types of texts', 'Have different types of texts: o narrative o expository o procedural; Compare the language, style, structure and purpose, as well as the ideas/themes/information in any two related texts.; Compare ideas through discussion, notes etc.', 170),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.5', 'Read silently and answer more complex comprehension questions on texts /passages', 'Skim for details.; Scan for main ideas.; Read for details and answer questions.; Relate passages to personal experiences.', 180),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.6', 'Show the effect a text has on the reader', 'Identify different literary devices used by the writer; Link the effect of the devices to the meaning of the text.; Identify the impact of literary devices on the reader and how they add to meaning.', 190),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.7', 'Interpret use of words/ phases (figurative, symbolic, sensory) in complex texts', 'Read a variety of texts.; Interpret text in simple sentences.; Identify the use of imagery for meaning; o The senses o Symbolism o Figurative language; Identify how language (words/ phrases) helps with interpreting meaning.', 200),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.8', 'Demonstrate conceptual understanding of academic, domain-specific, and technical vocabulary in varied context', 'Identify the use of different registers for specific texts.; Read texts that make distinctions in language use for a variety of purpose.; Use the right vocabulary in complex sentences/paragraphs.', 210),
('Basic 9', 'English Language', 'english', 'Reading', 'Comprehension', 'B9.2.1.2', 'Read, comprehend, and analyse varieties of texts', 'B9.2.1.2.9', 'Make conceptual connections between known and unknown words/phrases and analyse nuances of words/ phrases in texts', 'Read grade-appropriate texts.; Identify known and unknown words meaningfully.; Connect these words and phrases to the text and analyse the effect.', 220),
('Basic 9', 'English Language', 'english', 'Reading', 'Summarising', 'B9.2.2.1', 'Cite the textual evidence that supports an analysis of what the text says, determining the central idea of a text and provide an objective summary', 'B9.2.2.1.1', 'Analyse critically a given text in entirety and provide an objective summary', 'Analyse a text.; Identify the main and supporting ideas.; Provide an objective summary on the text. Provide answer questions for summary questions.', 230),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.1', 'Apply the knowledge of phrases and clauses and their functions in Communication', 'B9.3.1.1.1', 'Use noun phrases accurately in context', 'Use noun phrases in texts. e.g. i. I want a dress for Christmas. ii. The brown kente vase is up for sale. iii. I saw a beautiful bird. iv. Kwaku lives in a blue dorm. v. Having been a chef, he knew how to bake).; Determine and discuss the functions of noun phrases in texts. Functions: o subject of sentences – The tall lady teaches English in Bakano JHS. o subject complement – The man is an awesome welder. o direct object of transitive verbs – I like the sleek Apple laptop. o objects of prepositions – He bought a vehicle for the winner of the race. o apposition – My hometown, Tamale, is a wonderful place. Kwame Aidoo, the class prefect of Grade 8, is my friend.', 240),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.1', 'Apply the knowledge of phrases and clauses and their functions in Communication', 'B9.3.1.1.2', 'Demonstrate command using multiple adjectives in the correct order, and using quantifiers effectively in speaking and writing', 'Use adjective phrases to provide vivid descriptions of: o Participants - The dazzlingly beautiful winner walked down the aisle. The man covered with mud crawled his way out of the mudslide. o Settings – The journey begun on a rainy Monday morning. o Materials - Amma is wearing a bright coloured African print. o Objects - The old rickety bus stopped in the middle of the road.', 250),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.1', 'Apply the knowledge of phrases and clauses and their functions in Communication', 'B9.3.1.1.3', 'Use more complex phrasal verbs accurately in speech and writing', 'Identify phrasal verbs in texts and determine what they mean in context (come after, come along, blow up, make up, etc).; Use phrasal verbs in developing meaningful paragraphs.', 260),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.1', 'Apply the knowledge of phrases and clauses and their functions in Communication', 'B9.3.1.1.4', 'Use the knowledge of the adverbial phrase and its functions', 'Use adverb phrases to: o Describe how — e.g. Aysha passed the exam quite easily. o Describe where — e.g. I met Kwame near the bridge. o Describe why — e.g. The law was abolished to end discrimination of girls in school. o Describe when — e.g. The disgraced thief left the scene as quickly as possible.', 270),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.2', 'Demonstrate understanding of the use of conditional tenses in communication', 'B9.3.1.2.1', 'Use conditional sentences in communication to indicate an impossible condition in the past and its probable result', 'Use if- clauses to construct conditional sentences (type; 3) to refer to an impossible condition in the past and its probable result. E.g. If I had worked harder, I would have passed the exam. You could have been on time if you had caught the bus.; Construct and analyse given conditional sentences (1-3) into main clauses and subordinate clauses (if-clauses).', 280),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.2', 'Demonstrate understanding of the use of conditional tenses in communication', 'B9.3.1.2.2', 'Use defining and non-defining relative clauses appropriately in speech and writing', 'Apply the functions of dependent and independent clauses in sentences and texts.', 290),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.3', 'Demonstrate command of structural and functional use of sentences', 'B9.3.1.3.1', 'Identify and use subject and predicate in texts', 'Distinguish elements of a sentence.; Use the knowledge of the composition of subject.; Know the composition of predicate of a sentence.', 300),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.4', 'Demonstrate mastery of the use of active and passive voice', 'B9.3.1.4.1', 'Use passive forms appropriately in speech and in writing', 'Change active to passive sentences.; Construct an opinion using active and passive sentences in speech and in writing.', 310),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B9.3.1.4', 'Demonstrate mastery of the use of active and passive voice', 'B9.3.1.4.2', 'Demonstrate command of the use of reported speech', 'Use reported speech in oral communication.; Compose text using reported speech.', 320),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Punctuation and Capitalisation', 'B9.3.2.1', 'Demonstrate mastery of capitalisation and punctuation in communication', 'B9.3.2.1.1', 'Identify and use punctuation marks (dash, hyphen, bracket) in context', 'Use the dash to: o mark the beginning and the end of an interruption in a sentence. E.g. My son - where has he gone - will be happy to see you. o introduce an explanation of a word or an expression earlier mentioned. E.g. It was not a lion - it was a tiger - furiously lashing its way through the undergrowth. o introduce a list. E.g. Everyone needs good qualities – loyalty, discipline, honesty etc.; Use the hyphen to: o form compound words. E.g. father-in-law o join words in attributive compound. E.g. a well-known artist o join a prefix to a root word. E.g. co-ordinate o mark expressions that look the same but different. E.g. a poor-rate collection; a poor rate-collection. o separate two similar consonant or vowel sounds. E.g. pre-empt, Ross-shire etc. o indicate fractions or multipliers. E.g. two-thirds, hundred-folds etc; NDICATORS AND EXEMPLARS', 330),
('Basic 9', 'English Language', 'english', 'Grammar Usage', 'Vocabulary', 'B9.3.3.1', 'Demonstrate appropriate use of vocabulary and spelling conventions in communication', 'B9.3.3.1.1', 'Interpret vocabulary appropriately in more complex texts', 'Demonstrate appropriate use of vocabulary in context.', 340),
('Basic 9', 'English Language', 'english', 'Writing', 'Production and Distribution of Writing', 'B9.4.1.1', 'Develop, organise and express ideas coherently and cohesively in writing', 'B9.4.1.1.1', 'Compose logically connected paragraphs to show unity, completeness and coherence using appropriate cohesive devices,', 'e.g., connectors, pronouns, repetition of vocabulary or grammatical structures; Use coordinating conjunctions to join clauses in compound sentences: and, but, nor, or, so, then, yet.; Use subordinating conjunctions to join clauses in complex sentences: o time clauses: when, before, after, since, while, as, until o conditional clauses: if, unless o purpose clauses: in order to, so that o reason clauses: because, since, as o result clauses: so that o concessive clauses: although, though, while o place clauses: where, wherever o clauses of manner: as, like, the way.; Expand sentences in to paragraphs using defining and non-defining relative clauses. E.g. the men who stole the car were jailed. (defining) The women, who stole the car, were jailed. (non-defining) Differences between the two may show in the comma marks.; Use noun phrases, adjectival phrases and adverbial phrases to expand sentences.', 350),
('Basic 9', 'English Language', 'english', 'Writing', 'Production and Distribution of Writing', 'B9.4.1.1', 'Develop, organise and express ideas coherently and cohesively in writing', 'B9.4.1.1.2', 'Develop a paragraph to show paragraph unity and completeness using supporting details (', 'e.g. explanation, elaboration, definition, examples); Write paragraphs showing the topic sentence, minor and major supporting sentences using transitional devices to bring about cohesion and coherence, e.g. o and, again, and then, besides, equally important, finally, o whereas, but, yet, on the other hand, however, nevertheless o yet, still, however, nevertheless, in spite of,', 360),
('Basic 9', 'English Language', 'english', 'Writing', 'Production and Distribution of Writing', 'B9.4.1.2', 'Create different paragraphs a given topic (Please check for an omission here)', 'B9.4.1.2.1', 'Compose more complex paragraphs using appropriate strategies', 'Write mixed paragraph (paragraph with the topic sentence located in the middle) and periodic paragraphs (paragraph with the topic sentence at the end) using transitional devices to create effect and purpose.; Organise sentences in a logical sequence to create coherence and beauty that sustains interest in an introductory paragraph.; Use logical connectors to link sentences in a paragraph: o ordering ideas: firstly, secondly, finally, etc. o addition: moreover, furthermore, in addition, etc. o similarity: similarly, likewise, in the same way, etc. o contrast: however, nevertheless, although, though, on the other hand, etc. o cause/effect: because, therefore, as a result, consequently, etc. o conditions: if, provided that, unless, etc. o sequence in time: next, soon, after, then, later, suddenly, afterwards, etc.; Use logical connectors, pronouns and the repetition of words, synonyms and antonyms to create cohesion and coherence and unity and completeness of paragraph.', 370),
('Basic 9', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B9.4.2.1', 'Use a process approach to compose descriptive, narrative/ imaginative, informational and persuasive, argumentative texts', 'B9.4.2.1.1', 'Create effective descriptive sentences when describing characters, settings or mood', 'Write descriptive essays using the following: o multiple, powerful adjectives for effect o sentence structure for effect e.g. frontloading, listing, climactic sentence structure; Make selective use of detail for effect when describing a character.; Proofread to self-correct or peer correct.', 380),
('Basic 9', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B9.4.2.1', 'Use a process approach to compose descriptive, narrative/ imaginative, informational and persuasive, argumentative texts', 'B9.4.2.1.2', 'Use different narrative techniques to manipulate time in a story. Compose narrative essays showing the following', 'Backstory; Flashback and flash forward; Foreshadowing; Express feelings and thoughts through free writing on self-selected topics, using emotive/ sensory details', 390),
('Basic 9', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B9.4.2.1', 'Use a process approach to compose descriptive, narrative/ imaginative, informational and persuasive, argumentative texts', 'B9.4.2.1.3', 'Write a well-organised persuasive piece (', 'e.g. argumentative) that states and defends a position; Compose an argumentative piece suitable following appropriate format/style using process approach.; Use: o the simple present for conveying timeless statements and facts o modals for persuasive effect and hedging o mental verbs (e.g. I think, I believe) for conveying a viewpoint o verb phrases; Write a rejoinder for publication noting the following: o An address to the rejoinder. (own address .... ) o A date. After the address comes a date o A reference should be included. All rejoinders require references. o The recipient’s address.', 400),
('Basic 9', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B9.4.2.1', 'Use a process approach to compose descriptive, narrative/ imaginative, informational and persuasive, argumentative texts', 'B9.4.2.1.4', 'Write an informative, explanatory text on a familiar or unfamiliar topic', 'Write an informational text to show how and why something happened: o Vividly describe a situation. o Give details of how a problem/situation occurs - show what needs to be done - indicate how it needs to be done - tell why it will work; Use appropriate, objective language to explain points.; Organise ideas and points in an information text logically.; Using selected topics, write reports that are devoid of decisions based on personal bias, cultural differences and any other criterion that cannot be measured or proven', 410),
('Basic 9', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B9.4.2.2', 'Apply writing skills to specific life situations', 'B9.4.2.2.1', 'Compose formal writing (business letters, email, minutes, programme agenda reports) on given topics using appropriate format', 'Formal letters Use appropriate text features (e.g., section headings in letters/email, main and sub-headings, bullets/numbering) to write various formal letters on a variety of themes.; Provide information, explain a situation and/or express points of view:; Describe, elaborate on and/or support/explain key points; Apply the appropriate format (e.g. salutation in letters/email, signing off for notes/letters).; Use formal language, avoid using short forms and abbreviations.; Edit/Proofread the writing for sense or meaning, and effect.; Publish writing using various media including ICT.', 420),
('Basic 9', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B9.4.2.2', 'Apply writing skills to specific life situations', 'B9.4.2.2.2', 'Compose short text (flyers, posters, invitation cards, email, etc. ) for different purposes and audiences', 'Write flyers or posters of varied kinds using: o Small size e.g. A5 paper o Eye-catching headline, slogan or logo o Brief description of product o List of benefits or offers o Contact information e.g. website o Include a visual and or a design element; Design an invitation card to incorporate the following: o Nature of the event o Where it will take place o Date and time (could include dress code) o Name of invitee (could include RSVP) o Could have a visual and or a design element; Write emails to contacts, parents or teachers ensuring that the following are present: o The recipient’s address–which, in most cases, is the recipient’s name and the server point. For example, aziz65(name)@gmail. (server). o CC: These may be additional recipients whose attention are called to the email. o Subject: This is a summary of the content of the email. o Message o Sender’s name and contact.', 430),
('Basic 9', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B9.4.2.2', 'Apply writing skills to specific life situations', 'B9.4.2.2.3', 'Write articles (short reports, letters and case studies) on given issues for publication', 'Write short reports, case studies and letters to the Editor on given issues for publication, e.g. o Self-publication. o Letters to the Editor. o Newspapers & publications with a staff of writers. o Literary Magazines. o Other types of magazines. o Scholarly journals. o Webzines.', 440),
('Basic 9', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B9.4.2.2', 'Apply writing skills to specific life situations', 'B9.4.2.2.4', 'Compose speeches for different purposes and occasions', 'Compose a speech: o Tell what you are going to tell them (introduction) o Tell them (body). o Tell them what you told them (conclusion).; Use the following to create effect: o Emotive adjectives e.g. ‘Wonderful, magnificent, fantastic, disgraceful, shocking, outrageous.’ o Tripling e.g. “It’s your country, it’s my country, it’s our future!” o Repetition o Parallel sentence structure o Powerful imagery e.g. “I have a dream.” o Use of ‘we’ to include everyone (inclusive language) e.g. “We all know… you and I agree…”', 450),
('Basic 9', 'English Language', 'english', 'Writing', 'Building and Presenting Knowledge', 'B9.4.3.1', 'Research to build and present knowledge', 'B9.4.3.1.1', 'Conduct short research projects based on focused questions, and present key findings in writing', 'Identify issues of interest in your environment/school/community and conduct an investigation on them based on focused questions. E.g. Investigating into the different brands of a product and their prices, i.e., different brands of sachet/bottled water or variety of cocoa products (production and price). o Sample research questions What are the different types of cocoa products found in your area? How, where and from what is it produced? Manufacturing companies, prices, advertising and marketing? o Record, organise findings for presentation. o Make a list of references to avoiding plagiarism. o Individual/group presentation of findings. NB: Digital sources can be used to collect data (information).', 460),
('Basic 9', 'English Language', 'english', 'Writing', 'Building and Presenting Knowledge', 'B9.5.1.1', 'Demonstrate understanding of how various elements of literary genres contribute to meaning', 'B9.5.1.1.1', 'Analyse the use of language to convey characters in film/media, narratives and play scripts', 'Describe characters by their appearance, what they do, say, and what others say about them.', 470),
('Basic 9', 'English Language', 'english', 'Writing', 'Building and Presenting Knowledge', 'B9.5.1.1', 'Demonstrate understanding of how various elements of literary genres contribute to meaning', 'B9.5.1.1.2', 'Create monologues and dialogues narratives in play scripts', 'Identify monologues and dialogues in texts.; Create dialogue using appropriate punctuation.', 480),
('Basic 9', 'English Language', 'english', 'Writing', 'Building and Presenting Knowledge', 'B9.5.1.1', 'Demonstrate understanding of how various elements of literary genres contribute to meaning', 'B9.5.1.1.3', 'Analyse the sequence of events across texts (descriptive, auto-biography, biography, narrative and play script/ drama', 'Identify and explain the key events in film/media, narratives and play scripts.; Compare events across film/media, narratives and play scripts.; Create film/media, narratives and play scripts.', 490),
('Basic 9', 'English Language', 'english', 'Writing', 'Building and Presenting Knowledge', 'B9.5.1.1', 'Demonstrate understanding of how various elements of literary genres contribute to meaning', 'B9.5.1.1.5', 'Analyse common themes in texts', 'Identify common themes in film/media, narratives and play scripts.; Analyse common themes in film/media, narratives and play scripts.; Adapt a narrative form or style to compose own stories around given theme.; Use a range of ICT tools to present their composition. Note: The teacher should always encourage learners to reflect independently and critically on their writing.', 500),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Rites of Passage: Marriage', 'B9.1.1.1', 'Demonstrate an understanding of marriage of their culture and compare with other cultures of Ghana', 'B9.1.1.1.1', 'Discuss the processes involved in performing marriage rites in their culture', '1. Explain what marriage is.; 2. Read and discuss a text on marriage.; 3. Identify types of marriage.; 4. Identify some of the marriage rites in their culture and write them.; 5. Discuss marriage rites performance.; 6. Explore the significance of the processes involved in performing marriage rites.', 10),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Rites of Passage: Marriage', 'B9.1.1.1', 'Demonstrate an understanding of marriage of their culture and compare with other cultures of Ghana', 'B9.1.1.1.2', 'Compare and contrast the marriage rites in their culture to other cultures in Ghana', '1. Present marriage rites among their people.; 2. Relate the marriage rites of their culture to those of other Ghanaian cultures.', 20),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Rites of Passage: Marriage', 'B9.1.1.1', 'Demonstrate an understanding of marriage of their culture and compare with other cultures of Ghana', 'B9.1.1.1.3', 'Compare and contrast the traditional marriage rites to the contemporary marriage rites and dramatise both', '1. Explain some of the contemporary marriage rites in their culture.; 2. Compare and contrast the traditional to the contemporary marriage rites.; 3. Dramatise marriage rites session of their culture.', 30),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Naming Systems — Circumstantial, Reincarnation, Deity Names', 'B9.1.2.1', 'Exhibit knowledge of the understanding and application of circumstantial, reincarnation and deity names', 'B9.1.2.1.1', 'Identify and discuss circumstances that result in naming children in their community', '1. Explain circumstances that lead to circumstantial names.; 2. Write some of the names and relate them to the circumstances.; 3. Discuss the significance of circumstantial names.', 40),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Naming Systems — Circumstantial, Reincarnation, Deity Names', 'B9.1.2.1', 'Exhibit knowledge of the understanding and application of circumstantial, reincarnation and deity names', 'B9.1.2.1.2', 'Discuss reincarnation names and their meanings', '1. Identify reincarnation names and discuss their meanings.; 2. Discuss the significance of reincarnation names.', 50),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Naming Systems — Circumstantial, Reincarnation, Deity Names', 'B9.1.2.1', 'Exhibit knowledge of the understanding and application of circumstantial, reincarnation and deity names', 'B9.1.2.1.3', 'Identify and discuss deity names', '1. Explain circumstances that lead to giving new borns deity names. E.g.; Akan:Tutu, Antoa, etc; Dagaare: Gyebuni, Kala; Dagbani:Yabdoo,Tidoo; Dangme: Agbee, Nadu; Ewe: Afram, Klu; Ga: Nai, Dzan; Gonja: Kipo, Lansa; Nzema:Tanoɛ, Botokule; Kasem: Kukula; 2. Discuss the significance of deity names.', 60),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'The Clan System', 'B9.1.3.1', 'Demonstrate understanding and knowledge of the factors that militate against the clan system', 'B9.1.3.1.1', 'Discuss trends affecting the clan system', '1. Identify and discuss the trends affecting the clan system.; 2. Discuss ways by which the clan system can be strengthened.; 3. Discuss the similarities and differences between the various clan systems in their locality.', 70),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Chieftaincy:traditional Government', 'B9.1.4.1', 'Exhibit knowledge and understanding of the traditional governing structure (chief/ queenmother, chief priest, traditional military, sub chiefs, king makers) of their society and their duties', 'B9.1.4.1.1', 'Explore the traditional governing structure of their community and discuss the duties of the functionaries', '1. Read and discuss a text on traditional governance.; 2. Identify the traditional governing structure of their community.; 3. Discuss and write down the duties of the functionaries.; 4. Discuss and write the importance of the functionaries.', 80),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B9.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B9.2.1.1.1', 'Use appropriate register in everyday communication (informal and formal) with diverse partners on grade-level topics/ texts/issues', '1. Identify some slang words and jargons accepted locally and internationally.; 2. Use everyday, informal topics and situations that are more appropriate for the use of slang and jargon e.g. going out with friends, talking about music, hobbies, sport, and so on.; 3. Create and act scenes on texts/issues/topics using both formal and informal register to distinguish characters.', 90),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B9.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B9.2.1.1.2', 'Ask questions that link the ideas of several speakers and respond to others’ questions in a discussion', '1. Use open ended questions to enable speaker link ideas of other speakers on topics/issues e.g. In your opinion what are the views of people on bush fires, corruption, sanitation, energy conservation, ‘galamsey’, corona virus, Gender Equality and Social Inclusion (GESI), etc.?; 2. Listen attentively to view points on topics/issues in a conversation and respond appropriately.; 3. Engage in conversations on topics/issues with several speakers and respond to different views.', 100),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B9.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B9.2.1.1.3', 'Use appropriate language orally to discuss grade-level national issues fluently', '1. Identify grade-level national issues (the youth in agriculture, sanitation, life style diseases, free SHS, etc.); 2. Discuss grade-level national issues in detail using appropriate register.', 110),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B9.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B9.2.1.1.4', 'Express opinions and advice on a range of everyday issues and situations clearly', '1. Identify a range of everyday issues e.g. road/domestic accidents, domestic violence, child abuse.; 2. Engage in conversations on these issues giving your opinion and advice.', 120),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B9.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B9.2.1.1.5', 'Demonstrate appropriate turn taking and use techniques for effective argument (debate)', '1. Identify interesting topics/issues appropriate for argument and debate e.g.‘Children should be allowed to take decisions on matters concerning them.’; 2. Observe and use the skills of turn taking in arguments and debates.', 130),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Listening Comprehension', 'B9.2.2.1', 'Demonstrate the ability to listen to extended reading and identify key information', 'B9.2.2.1.1', 'Listen to a more natural level-appropriate interactions with multiple speakers', 'for example, TV shows, dramas, films, etc. Exemplars:; 1. Discuss and write key information e.g. message, theme, tone, mood in level appropriate texts/speeches.; 2. Listen to and compare information written from texts/speeches.', 140),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Listening Comprehension', 'B9.2.2.1', 'Demonstrate the ability to listen to extended reading and identify key information', 'B9.2.2.1.2', 'Initiate and participate in meaningful and collaborative discussions on texts and related materials building on others’ ideas and expressing their own clearly and persuasively', '1. Listen to and identify key issues in level appropriate texts/speeches/ dialogues e.g. argumentative texts, news, presentations.; 2. Initiate discussions on ideas and share opinions on level appropriate texts/ speeches/dialogues; 3. Engage in conferences to discuss ideas noted from texts/speeches/ dialogues and express their own clearly and persuasively', 150),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Tones', 'B9.2.4.1', 'Demonstrate knowledge and understanding in the use of the basic tones correctly in speaking and reading', 'B9.2.4.1.1', 'Apply the idea of tones correctly when speaking and reading in contexts', '1. Engage in a conversation on a given topic using the basic tones correctly.; 2. Read sentences using the correct tones.; 3. Read a passage using the correct tone patterns to depict the right context.', 160),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Presentation: Everyday Experiences', 'B9.2.6.1', 'Describe their everyday experiences on more complex topics using appropriate presentational skills', 'B9.2.6.1.1', 'Discuss complex topics related to everyday activities', '1. Read a text on deforestation in Ghana, same sex marriage, insecurity, etc.; 2. Discuss some of the everyday activities in the factory, traditional occupational shops, settlement of cases at the palace, etc.', 170),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Presentation: Everyday Experiences', 'B9.2.6.1', 'Describe their everyday experiences on more complex topics using appropriate presentational skills', 'B9.2.6.1.2', 'Compose their own group report on some topical issues', '1. Develop their own report on a range of suitable familiar and unfamiliar, concrete and abstract topics. Examples, pollution in Ghana, food production in Ghana, main industries in Ghana.; 2. Make a presentation on the topics above to the class for discussion.', 180),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Reading', 'B9.3.1.1', 'Read longer passages silently, identify main ideas, answer questions and summarise the passage', 'B9.3.1.1.1', 'Locate the main and subsidiary points in a range of texts and rewrite logically with accuracy in their own words', '1. Read and understand a passage of between 200-250 words from different subject areas silently.; 2. Identify the main ideas in the passage.; 3. Rewrite the ideas logically in their own words.; 4. Answer recall, meaning and inferential questions based on the passage.', 190),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Reading', 'B9.3.1.1', 'Read longer passages silently, identify main ideas, answer questions and summarise the passage', 'B9.3.1.1.2', 'Summarise passages read in given number of sentences', '1. Arrange the main ideas in a range of passages logically and coherently.; 2. Summarise a passage of two hundred words in fifty words.', 200),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Translation', 'B9.3.2.1', 'Demonstrate knowledge of translating texts from source language to the target language', 'B9.3.2.1.1', 'Decode the meaning of texts and translate from source to target language', '1. Translate texts of about one hundred words from source to a target language.; 2. Read and discuss the translated text.', 210),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (nouns, Adjectives)', 'B9.4.2.1', 'Demonstrate knowledge of the use of singular and plural nouns in sentences and passages', 'B9.4.2.1.1', 'Discuss nouns under singular and plural forms in an increasing and abstract range of texts', '1. Identify and classify nouns in a passage according to their singular and plural forms.; 2. Construct simple and compound sentences with the singular and plural nouns in speech and in writing.', 220),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (nouns, Adjectives)', 'B9.4.2.2', 'Demonstrate knowledge of how adjectives are combined in a sentence', 'B9.4.2.2.1', 'Discuss how adjectives follow each other in a sentence', '1. Identify adjectives in texts.; 2. Form sentences with two or three adjectives.', 230),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (verbs, Adverbs)', 'B9.4.3.1', 'Exhibit knowledge and understanding of the use of auxiliary verbs', 'B9.4.3.1.1', 'Discuss auxiliary verbs in sentences', '1. Identify types of verbs in a recorded/read passage.; 2. Discuss auxiliary verbs (where applicable).; 3. Construct sentences with auxiliary verbs.', 240),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (verbs, Adverbs)', 'B9.4.3.1', 'Exhibit knowledge and understanding of the use of auxiliary verbs', 'B9.4.3.1.3', 'Discuss how adverbs follow each other in a sentence', '1. Identify adverbs in texts.; 2. Construct sentences with two or three adverbs correctly.', 250),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Structure and Organise Ideas in Composition Writing', 'B9.5.1.1', 'Demonstrate knowledge and understanding of the features of the various text types discussed and use the knowledge to write a coherent essay on the text types', 'B9.5.1.1.1', 'Plan and structure a range of extended texts using paragraphs to show progression from one idea to the next and linking paragraphs using cohesive language', '1. Write a coherent essay on any of the text types (e.g. narrative, descriptive, creative, academic, and argumentative and letter writing) on a given topic.; 2. Identify and write the topic and supporting sentences in the paragraphs.', 260),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Literature', 'Drum/horn/xylophone Language, Prose, Poetry and Drama', 'B9.6.1.1', 'Demonstrate an understanding of drum language, appellations and war songs', 'B9.6.1.1.1', 'Explore drum language/appellations and war songs respectively', '1. Describe the features of drum language/appellation.; 2. Discuss drum language/appellation.; 3. Discuss the occasions/situations on/in which drum language/appellation is used.; 4. State the importance of drum language/appellation.; 5. Appreciate war songs in your language.; 6. Discuss the importance of war songs.', 270),
('Basic 9', 'Ghanaian Language', 'ghanaian language', 'Literature', 'Drum/horn/xylophone Language, Prose, Poetry and Drama', 'B9.6.1.2', 'Demonstrate knowledge and understanding in the writer’s use of language in a prose, poetry and drama texts', 'B9.6.1.2.1', 'Discuss how writers use language to create effect in an increasing range of prose, poetry and drama', '1. Discuss characterisation in relation to prose, poetry and drama texts and give examples from texts.; 2. Explore ways that writers use a wide range of literary devices (personification, alliteration, assonance) in a range of prose, poetry and drama texts.; 3. Discuss how writers use settings to create different effects in a range of prose, poetry and drama.; 4. Discuss how writers use language to create mood and tone in an increasing range of prose, poetry and drama; 5. Discuss the ways writers structure texts in a range of prose, poetry and drama texts.', 280),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number and Numeration System', 'B9.1.1.1', 'Apply the understanding of place value in solving real life problems involving integers of any size, rounding this to given decimal places and significant figures', 'B9.1.1.1.1', 'Express integers to a given number of significant and decimal places', 'E.g.1. Express integers to a number of significant figures. (i) 857,386,321 -five significant figures -four significant figures -three significant figures.; E.g.2. Express decimal numbers to a given number of decimal places. (i) Write 98745.9674 correct to -three decimal places -two decimal places -one decimal place', 10),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number and Numeration System', 'B9.1.1.1', 'Apply the understanding of place value in solving real life problems involving integers of any size, rounding this to given decimal places and significant figures', 'B9.1.1.1.2', 'Use knowledge and understanding of place value to solve real life problems', 'E.g.1. Create and solve a real-life problem or a story problem and write the answer in standard form. (I) I am a 6-digit number. My first digit is 5 more than the last digit, but 2 less than my second digit. My second digit is the third multiple of 3, while my fourth digit is the second multiple of 3. My third digit is the quotient when the fourth digit is divided by my last digit. However, my fourth and fifth digits are consecutive numbers. What number am I?', 20),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number and Numeration System', 'B9.1.1.2', 'Demonstrate an understanding of the relationship between members of the rational number system and solve real life problems involving union and intersection of three sets', 'B9.1.1.2.1', 'Solve problems on relationship between members of the rational number system using knowledge and understanding of the concept of union and intersection of two sets', 'E.g. 1 Use sets diagrams to show the relationship among the Real numbers namely; -Irrational numbers (QI) -Rational numbers (Q) - Integers (Z) -Whole numbers (W) -Natural or Counting numbers (N)', 30),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number and Numeration System', 'B9.1.1.2', 'Demonstrate an understanding of the relationship between members of the rational number system and solve real life problems involving union and intersection of three sets', 'B9.1.1.2.2', 'Apply the concept of sets to solve problems on relationship between members of rational number system and solve real life problems involving union and intersection of two sets', 'E.g.1 Create and solve real life problems to show the union and intersection of two sets. i. There are 80 farmers in a certain village who grow either maize or beans. Fifty of them grow beans while sixty grow maize. If each farmer grows at least one of the two crops, represent the information on a Venn diagram and hence find the number of farmers who grow: a. both crops. b. only one crop.', 40),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B9.1.2.1', 'Demonstrate an understanding of the relationship between members of the rational number system and solve real life problems involving union and intersection of three sets', 'B9.1.2.1.1', 'Multiply and divide given numbers by powers of 10 including', 'decimals and benchmark fractions; E.g.1. Recall multiplication facts up to 144 and related division facts.; E.g.2. Recall decimal names of given benchmark fractions converted to decimals; or percentages (and vice versa); E.g. 3. Find the product of a given decimal number when it is multiplied by 10,; 100, 1000, , , etc. 1 1 1', 50),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B9.1.2.1', 'Demonstrate an understanding of the relationship between members of the rational number system and solve real life problems involving union and intersection of three sets', 'B9.1.2.1.3', 'Use the associative property of addition and multiplication', 'E.g1. Recognise that for any three numbers a, b and c; i. a + (b + c) = (a + b) + c or a + (b + c) = (a + c) + b i.e. 15 + (6 + 9) = (15 + 6) + 9 = 30 ii. (a × b) × c = a × (b × c) i.e. (12 × 5) × 4 = 12 × (5 × 4) = 240', 60),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B9.1.2.1', 'Demonstrate an understanding of the relationship between members of the rational number system and solve real life problems involving union and intersection of three sets', 'B9.1.2.1.4', 'Use the distributive property in solving problems', 'E.g1. Recognise that for any three numbers a, b and c; i. a × (b + c) = (a × b) + (a × c) i.e. 5 × (10 + 7) = (5 × 10) + (5 × 7) = 85 ii. a × (b - c) = (a × b) - (a × c) i.e. 5 × (10 - 7) = (5 × 10) - (5 × 7) = 15', 70),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B9.1.2.2', 'Apply the understanding of addition, subtraction, multiplication and division of decimal numbers to solve problems, and round answers to given decimal places and significant figures', 'B9.1.2.2.1', 'Solve operations involving addition, subtraction, multiplication and division using word problems', 'E.g. Create and solve story problems involving a combination of two or more of the basic operations. (×, ÷, ─,+). i) A trader sells oranges from two baskets, A and B. Basket A contained 85 oranges and she sold 48. She sold 59 oranges from basket B and was left with the same number of oranges as in Basket A. How many oranges were originally in Basket B?', 80),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B9.1.2.2', 'Apply the understanding of addition, subtraction, multiplication and division of decimal numbers to solve problems, and round answers to given decimal places and significant figures', 'B9.1.2.2.2', 'Solve word problems involving the four basic operations and round the answers to the nearest two decimal figures or to some significant figures', 'ii) The price of a jacket is three times that of a shirt. The price of a jacket is GH₵560.65. Mr Mensa bought two of the jackets and four shirts for his twin sons. Calculate the total amount Mr Mensa paid for the items, correct your answer to: ) two decimal places 𝛼𝛼 three significant figures', 90),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B9.1.2.3', 'Demonstrate understanding of surds as real numbers, the process of adding and subtracting of surds as well as determining (using a calculator) the approximate square root of a number that is not a perfect square', 'B9.1.2.3.4', 'Approximate the square roots of non-perfect squares with calculators/tables', 'E.g.1 Square roots of non-perfect squares i. ii. √2 iii. √5 iv. √12 √30', 100),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B9.1.2.4', 'Demonstrate understanding of surds as real numbers, the process of adding and subtracting of surds as well as determining (using a calculator) the approximate square root of a number that is not a perfect square', 'B9.1.2.4.1', 'Identify simple and compound surds', 'E.g. i.√2, ii.7√3, iii. 2√5; iBv9.(.1√.32.+4.√2 7E−xp√la5i)n the identities/rules of surds; Rule 1 √R𝑎𝑎ul×e 𝑎𝑎2 = √𝑎𝑎×√𝑎𝑎 𝑎𝑎 √𝑎𝑎 √ = R𝑎𝑎ule 3√ 𝑎𝑎 𝑎𝑎 𝑎𝑎 √𝑎𝑎 𝑎𝑎√𝑎𝑎 = × = √𝑎𝑎 √𝑎𝑎 √𝑎𝑎 𝑎𝑎', 110),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B9.1.2.4', 'Demonstrate understanding of surds as real numbers, the process of adding and subtracting of surds as well as determining (using a calculator) the approximate square root of a number that is not a perfect square', 'B9.1.2.4.3', 'Simplify given surds', 'E.g.1 Simplify: i. √27 i. √72 ii. √8 16 iii. √12 121 iv. 2', 120),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Fractions, Decimals and Percentages', 'B9.1.3.1', 'Apply the understanding of operations on fractions to solve problems involving fractions of given quantities and round the results to given decimal and significant places', 'B9.1.3.1.1', 'Review fractions and solve problems involving basic operations on fractions', 'E.g. 1. Review the concept of fraction.; i. Shade the fraction of squares in the rectangle that is equal to the shaded portion of the circle. ii. Write down 3 fractions equivalent to 2 iii. Express the fraction in its simplest form: 5 15 15 iv. Express as a mixed number: 10 10 12 12 v. Express 2 as an improper fraction: 2 5 5 5 5; 9 9 E.g. 2. Review the basic operations on fractions. i. Adding and subtracting fractions: Work out answers to the following: a) b) − 3 7 1 4 5 ii. Multiply4i+ng 8and dividin1g2 f+rac5tio6ns. Work out answers to the following: a) × − b) ÷ 2 3 3 5 1 2', 130),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Fractions, Decimals and Percentages', 'B9.1.3.1', 'Apply the understanding of operations on fractions to solve problems involving fractions of given quantities and round the results to given decimal and significant places', 'B9.1.3.1.2', 'Add and/or subtract, multiply and/or divide given fractions, using the principle of order of operations including the use of the BODMAS or PEMDAS rule, and apply the understanding of these to solve problems', 'E.g.; 1. Use the order of operations (BODMAS or PEDMAS) to simplify whole number expressions with more than two operations. PEDMAS is Parenthesis, Exponents, Multiply/Divide (going from left to right)and Add/subtract (going from left to right). i. 34 ÷ 32 + 40 – 23 × 32 ÷ 9 ii. 18 ÷ 6 × (4 -; 3) + 6 iii. 18 ÷ 32 × (4 -; 3) × 10 E.g.; 2. Use the order of operations (BODMAS or PEDMAS) to simplify fractions with more than two operations. a) × − ÷ 2 3 5 1 b) 3 4 8 2 −2 ) 3 3 4 1 4 ÷ 8+(5 2 c) ( − 3 5 4 1', 140),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Fractions, Decimals and Percentages', 'B9.1.3.1', 'Apply the understanding of operations on fractions to solve problems involving fractions of given quantities and round the results to given decimal and significant places', 'B9.1.3.1.3', 'Review word problems involving basic operations on fractions', 'E.g. 1. Solve word problems based on fractions. i. A test is made up of 20 questions, how many questions must you answer correctly to get a score of 80%? ii. By what percentage was a television set reduced if it was marked GH₵2,250 and sold for GH₵2,025? iii. In an election involving two contestants, one candidate claimed 52% of the votes, while the other candidate claimed 2,681 votes. If 5000 people voted, how do you know the election results are invalid? iv. Esi and Fusena prepared orange drink by mixing orange squash and water. Esi’s drink was made of orange squash and Fusena’s was 3 made up of orange squash. Whose drink tasted stronger of orange? 8 2', 150),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number: Ratios and Proportion', 'B9.1.4.1', 'Apply the understanding of ratio, rate and proportions to solve problems that involve rates, ratios, and proportional reasoning and use it to solve real- world mathematical problems', 'B9.1.4.1.1', 'Represent proportional relationships by equations', 'E.g.1 If total cost (t) is proportional to the number of items (n) purchased at a constant price (p), the relationship between the total cost and the number of items can be expressed as t = pn.', 160),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number: Ratios and Proportion', 'B9.1.4.1', 'Apply the understanding of ratio, rate and proportions to solve problems that involve rates, ratios, and proportional reasoning and use it to solve real- world mathematical problems', 'B9.1.4.1.2', 'Use proportional relationships to solve multistep ratio and percent problems,', 'simple interest, tax, discount and commissions, NHIL, depreciation, insurance, etc.; E.g.1 Solve problems on simple interest. i. A girl deposited GH₵ 4500 at the bank at a rate of 3% per annum for three years. Find the simple interest. What is the amount at the end of the fifth year?; E.g.2 Solve problems on tax (VAT). i. The VAT rate of Ghana is 12.5%. A man bought an item at GH₵ 4500.00, VAT inclusive. Calculate: b) the basic cost of the item. c) the VAT paid by the man.; E.g.3 Solve problems on discount. i. If a car costs GH₵ 80,500.00,what is its new value if there is a discount of 10%? E.g.4 Solve problems on commission. ii. A car agent’s commission on the sale of a car is %. Calculate the 1 commission on a car sold for GH₵68,000.00.; E.g.5 solve problems involving depreciation. The value of a mobile phone depreciates at the following rate: Year of Depreciation on manufacture the original value In the first year 5% In the second year 10% In the third year 15% In the fourth year 22% The original value of the mobile phone is GH₵ 1800.00. Find the value of the mobile phone at the end of each of the first four years.; E.g.6 Solve problems involving NHIL. i. The NHIL inclusive price of a television set is GH₵1200.00. If the NHIL is charged at a rate of 2.5%, find b) the cost of the television set (NHIL exclusive). c) the NHIL charged.; E.g.7 Solve problems involving insurance. i. Kofi Mereku insured his house and paid a premium of GH₵ 30,000.00. If the insurance company fixed the rate at 5% of the value of the house, calculate the insured value of the house.', 170),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number: Ratios and Proportion', 'B9.1.4.1', 'Apply the understanding of ratio, rate and proportions to solve problems that involve rates, ratios, and proportional reasoning and use it to solve real- world mathematical problems', 'B9.1.4.1.3', 'Use knowledge of rates and proportional reasoning to solve problems involving SSNIT benefits and contributions', 'E.g.1 Describe the obligations of the employer/employee and the contribution rates. Act 766 PNDC Law 247 Employer 13.0% of basic salary 12.5 of basic salary Worker 5.5% of basic salary 5.0% of basic salary Total 18.5% of basic salary 17.5% of basic salary', 180),
('Basic 9', 'Mathematics', 'maths', 'Number', 'Number: Ratios and Proportion', 'B9.1.4.1', 'Apply the understanding of ratio, rate and proportions to solve problems that involve rates, ratios, and proportional reasoning and use it to solve real- world mathematical problems', 'B9.1.4.1.4', 'Recognise and graph proportional relationships, interpreting the unit rate as the slope of the graph and use these to solve problems', 'E.g.1The graph below shows the cost of avocados. The unit rate, from the data, is ₵1.50 per avocado, which is the same as the slope of the line connecting the data points ( 3 i. From the graph, how much does eight avocados cost? 2). ii. Also, using the graph how much does 15 avocados cost?', 190),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relations', 'B9.2.1.1', 'Demonstrate the ability to construct tables of values for pairs of linear relations, graph the relations in a number plane and determine the intersection of the lines to solve simultaneous linear equations', 'B9.2.1.1.1', 'Construct a table of values for two linear relations and graph the relation', 'E.g.1Construct a table of values for two linear relations and draw the graphs of the relations Copy and complete the table of values for the relations and for from - 1 4 to 3. 𝑦𝑦1 = −𝑥𝑥+5; 𝑦𝑦2 = 2𝑥𝑥−3 𝑥𝑥 -3 -2 -1 0 1 2 3 𝑥𝑥 8 4 𝑦𝑦1 = −𝑥𝑥+5 -4 - 1.5 1 2; 𝑦𝑦 = 𝑥𝑥−3 2 E.g.3Construct a table of values for two linear relations. (i) Copy and complete the table of values for the relations and for from -2 to 2. 𝑥𝑥−2𝑦𝑦 = −2 𝑥𝑥−2𝑦𝑦 = 2 𝑥𝑥 x -2 -1 0 1 2 𝑥𝑥 y 0 2 𝑥𝑥−2𝑦𝑦 = (𝑥𝑥+2)/ = −2 2 - 0 1 𝑥𝑥−2𝑦𝑦 =2 = (𝑥𝑥−2)/2 12', 200),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relations', 'B9.2.1.1', 'Demonstrate the ability to construct tables of values for pairs of linear relations, graph the relations in a number plane and determine the intersection of the lines to solve simultaneous linear equations', 'B9.2.1.1.2', 'Use graphs of two linear relations to determine subsequent missing elements in ordered pairs of the relation', 'E.g.1 Find the missing elements of ordered pairs on graphs of two linear relations. The graph below is drawn from two linear relations: 𝑦𝑦 = −𝑥𝑥+ 4 i. 𝑦𝑦D=e𝑥𝑥te−rm2ine the coordinates for the intersection of the two lines. ii. Determine the corresponding values for y for both straight lines if x = -1. iii. Use the graph to find the values for y for the two relations. 6-3 7-2 8-1 90 1 2 𝑥𝑥 𝑦𝑦 =−𝑥𝑥+4 𝑦𝑦 = 𝑥𝑥−2', 210),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relations', 'B9.2.1.1', 'Demonstrate the ability to construct tables of values for pairs of linear relations, graph the relations in a number plane and determine the intersection of the lines to solve simultaneous linear equations', 'B9.2.1.1.3', 'Use graphs to solve equations involving two linear relations', 'E.g.1 Solve two linear equations simultaneously using the graph shown. i. Solve the following equations simultaneously using a graph. 𝑦𝑦 = −𝑥𝑥+7 Hin𝑦𝑦t: =Dr2a𝑥𝑥w+ th1e graph and find the coordinates for the intersection of the two lines. In the graph shown the values of (x, y) = (2, 5); E.g.2 Solve two linear equations simultaneously using the graph. From the graph, determine the values of x and y that makes the linear equations true. 𝑦𝑦 = 𝑥𝑥+4 𝑦𝑦 = 6−𝑥𝑥', 220),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Algebraic Expressions', 'B9.2.2.1', 'Demonstrate an understanding of (i) change of subject (ii) substituting values to evaluate expressions, and (iii) factorize expressions that have simple binomial as a factor', 'B9.2.2.1.1', 'Perform change of subject of a given formula and use it to solve problems', 'E.g.1 Perform change of subject for given formulae (i) Make the subject of the following formulae 𝑥𝑥', 230),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Algebraic Expressions', 'B9.2.2.1', 'Demonstrate an understanding of (i) change of subject (ii) substituting values to evaluate expressions, and (iii) factorize expressions that have simple binomial as a factor', 'B9.2.2.1.2', 'Substitute values into given formulae to evaluate it and use it to solve problems', 'E.g.1 i. Find the value of 𝟐𝟐 (𝒙𝒙−𝒃𝒃) –𝟑𝟑(𝒙𝒙−𝒃𝒃) 𝒊𝒊𝒊𝒊𝒙𝒙= 𝟐𝟐 𝒂𝒂𝒂𝒂𝒂𝒂 𝒃𝒃= −𝟓𝟓 ii. Make the subject of the formula: 𝒌𝒌 𝟐𝟐 𝟐𝟐 𝟏𝟏 𝒌𝒌 +𝒂𝒂 = √( ) 𝒂𝒂 𝒉𝒉𝒉𝒉 If 8 𝒂𝒂 = 5, 𝑎𝑎 = 3, ℎ = 2, 𝑔𝑔 =32,find the value of k. iii. The formula for finding the volume of the shape below is given as Find the volume 1 2 22 3𝜋𝜋𝑜𝑜 ℎ . if r= 7, h = 21,and π= 7', 240),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Algebraic Expressions', 'B9.2.2.1', 'Demonstrate an understanding of (i) change of subject (ii) substituting values to evaluate expressions, and (iii) factorize expressions that have simple binomial as a factor', 'B9.2.2.1.3', 'Factorise expressions that have simple binomial', 'E.g. Factorise the following expressions. i. 3x + 4xy = x (3 +4y) ii. 12ab + 16b = 4b (3a +; 4) iii. -13xy + 39x= -13x(y-3) iv. 5y-2y2+3y=-3y+3y v. 8y-2y2= 2y(4-y) vi. -6x+12=-3(2x-4)', 250),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Algebraic Expressions', 'B9.2.2.1', 'Demonstrate an understanding of (i) change of subject (ii) substituting values to evaluate expressions, and (iii) factorize expressions that have simple binomial as a factor', 'B9.2.2.1.4', 'Use the knowledge of simplifying and factorising expressions to solve real world problems', 'E.g.1 You purchased 10 items from a shopping plaza, and now you need plastic bags to carry them home. If each bag can hold only 3 items, how many plastic bags will you need to accommodate the10 items? Solution: We use simple algebraic formula to calculate the number of bags. 𝑥𝑥 x = Number of items purchased = 10 𝑦𝑦 y = Capacity of 1 bag = 3 Hence, = 3.333 bags 10 3= 4 bags So, we need 4 shopping bags to carry 10 items.', 260),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Variables and Equations', 'B9.2.3.1', 'Demonstrate understanding of single variable linear inequalities with rational coefficients including: • solving inequalities • verifying • comparing • graphing', 'B9.2.3.1.1', 'Solve single variable linear inequalities with rational coefficients', 'i. 𝟓𝟓 𝟐𝟐𝒙𝒙+𝟕𝟕 > 𝟐𝟐 ii. 𝟓𝟓 𝟏𝟏 𝟐𝟐 𝟓𝟓−𝟓𝟓𝒙𝒙 > 𝟕𝟕 iii. 𝟑𝟑 𝟐𝟐 𝟓𝟓 𝟐𝟐𝒚𝒚−𝟓𝟓< 𝟓𝟓 iv. 𝟏𝟏 𝟏𝟏𝟏𝟏', 270),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Variables and Equations', 'B9.2.3.1', 'Demonstrate understanding of single variable linear inequalities with rational coefficients including: • solving inequalities • verifying • comparing • graphing', 'B9.2.3.1.2', 'Illustrate solution sets of linear inequalities on the number line', 'E.g.1 Illustrate and explain the inequality signs', 280),
('Basic 9', 'Mathematics', 'maths', 'Algebra', 'Variables and Equations', 'B9.2.3.1', 'Demonstrate understanding of single variable linear inequalities with rational coefficients including: • solving inequalities • verifying • comparing • graphing', 'B9.2.3.1.3', 'Solve real-life problems involving linear equations and inequalities', 'E.g.1 Solve real-life problems involving linear equations. i. A man has 260metres of fencing which he is going to put around a rectangular field which is 50metres wide. How long is the field? Solution: Since we need to find the length of the field, let be x metres the length. 𝑥𝑥+50+𝑥𝑥+50 𝑜𝑜𝑜𝑜 2(𝑥𝑥+50) But this expression is given as 260m ∴ 2(𝑥𝑥+50)= 260 𝑥𝑥+50= 130', 290),
('Basic 9', 'Mathematics', 'maths', 'Geometry and Measurement', 'Shapes and Space', 'B9.3.1.1', 'Apply the properties of angles at a point, angles on a straight line, vertically opposite angles, corresponding, angles to` solve problems', 'B9.3.1.1.1', 'Derive the formula for calculating the sum of angles in any polygon and use this to calculate the value of missing angles in polygons', 'E.g.1. Identify and name the various polygons such as a triangle, quadrilaterals, pentagons, and hexagons, etc.', 300),
('Basic 9', 'Mathematics', 'maths', 'Geometry and Measurement', 'Shapes and Space', 'B9.3.1.1', 'Apply the properties of angles at a point, angles on a straight line, vertically opposite angles, corresponding, angles to` solve problems', 'B9.3.1.1.2', 'Identify similar and congruent triangles and use the knowledge to solve related problems E.g.1', 'Recognise similar triangles and solve for the values of the indicated angles in the diagram below:; E.g.2. Recognise congruent triangles and solve for the values of the indicated angles in the diagram below:; E.g. 3. Determine the value of x (using knowledge in similarity and congruency).', 310),
('Basic 9', 'Mathematics', 'maths', 'Geometry and Measurement', 'Shapes and Space', 'B9.3.1.2', 'Construct inscribed and circumscribed triangles and parallelograms with given dimensions', 'B9.3.1.2.1', 'Draw inscribed and circumscribed circles for triangles under given conditions', 'E.g.1: Use a pair of compasses and a ruler to construct a triangle (say ABC) under a given condition and locate the incentre of the triangle (the incentre is the point of concurrency of the three angle bisectors of a ∆ triangle); measure the shortest distance from the incentre to the line segments AB, AC and BC. What do you observe about the lengths?; E.g.4: Perform a geometric construction of a triangle (say ) under a given condition; bisect at least any two sides ( ); locate the intersection of 𝐴𝐴𝐴𝐴𝐶𝐶 the two perpendicular bisectors and draw a locus of points equidistant 𝐴𝐴𝐴𝐴 and 𝐴𝐴𝐶𝐶 from the fixed point to circumscribe the triangle. (𝐵𝐵) (𝐵𝐵)', 320),
('Basic 9', 'Mathematics', 'maths', 'Geometry and Measurement', 'Shapes and Space', 'B9.3.1.2', 'Construct inscribed and circumscribed triangles and parallelograms with given dimensions', 'B9.3.1.2.2', 'Construct parallelograms (i.e. square, rectangle, rhombus) under given conditions', 'E.g.1: Perform geometric construction of a square with a given side.', 330),
('Basic 9', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B9.3.2.1', 'Construct inscribed and circumscribed triangles and parallelograms with given dimensions', 'B9.3.2.1.1', 'Identify cuboids and triangular prisms; draw their nets to construct the 3-D shapes and use it to determine the surface area', 'E.g.1 Sort out shapes that are triangular prisms and cuboids. E.g.2 Identify each of the nets below: A net of…………….. A net of……………..', 340),
('Basic 9', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B9.3.2.1', 'Construct inscribed and circumscribed triangles and parallelograms with given dimensions', 'B9.3.2.1.2', 'Use the net of a cuboid to determine its surface area', 'E.g.1 Find the surface area of each of the cuboids', 350),
